INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.NUMBER_CONCEPT.ORDER_BY_SIZE.M_ORDER_REVERSED', 'MATH.G3.NUMBER.NUMBER_CONCEPT.ORDER_BY_SIZE', 'Orders from largest to smallest when asked for smallest to largest.', '{"question":"Put these sticks from the shortest to the longest: 8 cm, 3 cm, 5 cm.","wrong_answer":"8, 5, 3","correct_answer":"3, 5, 8"}'::jsonb, 'Does not attend to the direction words.', 'The answer 8, 5, 3 as a wrong option, with a reason that names the idea.', 'Point to the start and say ''shortest first''; place the first object before the others.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.NUMBER_CONCEPT.ORDER_BY_SIZE.M_ORDER_BY_POSITION', 'MATH.G3.NUMBER.NUMBER_CONCEPT.ORDER_BY_SIZE', 'Keeps the objects in the order they were shown, or in the order they lie on the table.', '{"question":"A bottle, a cup and a jerrycan are shown in that order. Order them from smallest to largest.","wrong_answer":"bottle, cup, jerrycan","correct_answer":"cup, bottle, jerrycan"}'::jsonb, 'Reads the order of the picture as the order of size.', 'The answer bottle, cup, jerrycan as a wrong option, with a reason that names the idea.', 'Compare two at a time by holding them side by side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.NUMBER_CONCEPT.ORDER_BY_SIZE.M_ORDER_TOPS_NOT_LENGTH', 'MATH.G3.NUMBER.NUMBER_CONCEPT.ORDER_BY_SIZE', 'Compares the tops of objects that do not start at the same line.', '{"question":"Two pencils: one starts further up the table. Which is longer?","wrong_answer":"the one that reaches higher","correct_answer":"the one that is longer from end to end"}'::jsonb, 'Looks only at where the objects end.', 'The answer the one that reaches higher as a wrong option, with a reason that names the idea.', 'Line up one end of every object first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.NUMBER_CONCEPT.ORDER_BY_SIZE.M_ORDER_MIDDLE_LOST', 'MATH.G3.NUMBER.NUMBER_CONCEPT.ORDER_BY_SIZE', 'Finds the smallest and largest but puts the middle objects in any order.', '{"question":"Order from smallest to largest: 4 stones of different sizes.","wrong_answer":"smallest, third largest, second largest, largest","correct_answer":"smallest, second smallest, second largest, largest"}'::jsonb, 'Compares only with the two ends.', 'The answer smallest, third largest, second largest, largest as a wrong option, with a reason that names the idea.', 'After the first, choose the smallest of those left, again and again.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.NUMBER_CONCEPT.ORDINAL_POSITION_20.M_ORD_WRONG_END', 'MATH.G3.NUMBER.NUMBER_CONCEPT.ORDINAL_POSITION_20', 'Counts the position from the wrong end of the line.', '{"question":"Ten children stand in a queue. Amina is 3rd from the front. How many children are in front of her?","wrong_answer":"7","correct_answer":"2"}'::jsonb, 'Counts from the back, or counts the children behind.', 'The answer 7 as a wrong option, with a reason that names the idea.', 'Mark the front with a flag and always start counting there.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.NUMBER_CONCEPT.ORDINAL_POSITION_20.M_ORD_IN_FRONT_EQUALS_POSITION', 'MATH.G3.NUMBER.NUMBER_CONCEPT.ORDINAL_POSITION_20', 'Says the number of people in front is the same as the position.', '{"question":"Otieno is 5th in the line. How many people are in front of him?","wrong_answer":"5","correct_answer":"4"}'::jsonb, 'Counts Otieno himself among those in front.', 'The answer 5 as a wrong option, with a reason that names the idea.', 'Line up 5 children and count those in front of the 5th.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.NUMBER_CONCEPT.ORDINAL_POSITION_20.M_ORD_SKIPS_IN_COUNT', 'MATH.G3.NUMBER.NUMBER_CONCEPT.ORDINAL_POSITION_20', 'Loses the count past 10 and names the next position wrongly.', '{"question":"What position comes after 12th?","wrong_answer":"14th","correct_answer":"13th"}'::jsonb, 'Counts the positions too fast past ten.', 'The answer 14th as a wrong option, with a reason that names the idea.', 'Touch each object and say each position aloud.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.NUMBER_CONCEPT.ORDINAL_POSITION_20.M_ORD_CARDINAL_CONFUSION', 'MATH.G3.NUMBER.NUMBER_CONCEPT.ORDINAL_POSITION_20', 'Answers with how many there are instead of the position.', '{"question":"There are 8 mangoes in a row. Which position is the last mango in?","wrong_answer":"8 mangoes","correct_answer":"8th"}'::jsonb, 'Mixes counting how many with naming a position.', 'The answer 8 mangoes as a wrong option, with a reason that names the idea.', 'Ask ''how many?'' and ''which one?'' as two questions.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.NUMBER_CONCEPT.WRITE_ORDINALS.M_ORDW_TH_EVERYWHERE', 'MATH.G3.NUMBER.NUMBER_CONCEPT.WRITE_ORDINALS', 'Writes ''th'' after every number, as 1th, 2th, 3th.', '{"question":"Write the position second in symbols.","wrong_answer":"2th","correct_answer":"2nd"}'::jsonb, 'Learnt the ''th'' ending and uses it for all.', 'The answer 2th as a wrong option, with a reason that names the idea.', 'Show 1st, 2nd and 3rd as the three special endings; from 4th to 20th the ending is th.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.NUMBER_CONCEPT.WRITE_ORDINALS.M_ORDW_SPELLING_TWELFTH', 'MATH.G3.NUMBER.NUMBER_CONCEPT.WRITE_ORDINALS', 'Spells the irregular words as they sound, as twelveth, fiveth or nineth.', '{"question":"Write 12th in words.","wrong_answer":"twelveth","correct_answer":"twelfth"}'::jsonb, 'Adds -th to the counting word.', 'The answer twelveth as a wrong option, with a reason that names the idea.', 'List the special spellings: fifth, ninth, twelfth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.NUMBER_CONCEPT.WRITE_ORDINALS.M_ORDW_CARDINAL_WORD', 'MATH.G3.NUMBER.NUMBER_CONCEPT.WRITE_ORDINALS', 'Writes the counting word instead of the position word.', '{"question":"Write 3rd in words.","wrong_answer":"three","correct_answer":"third"}'::jsonb, 'Does not tell number words and position words apart.', 'The answer three as a wrong option, with a reason that names the idea.', 'Say ''the third child'', ''three children'' and hear the difference.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.NUMBER_CONCEPT.WRITE_ORDINALS.M_ORDW_REVERSED_TEEN', 'MATH.G3.NUMBER.NUMBER_CONCEPT.WRITE_ORDINALS', 'Writes a teen position with the digits reversed, as 41st for fourteenth.', '{"question":"Write fourteenth in symbols.","wrong_answer":"41th","correct_answer":"14th"}'::jsonb, 'Hears ''four'' first and writes the 4 first.', 'The answer 41th as a wrong option, with a reason that names the idea.', 'Fourteen is ten and four: write the 1 for the ten first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.WHOLE_NUMBERS.COUNT_FORWARD_1000.M_CNT_STUCK_AT_HUNDRED', 'MATH.G3.NUMBER.WHOLE_NUMBERS.COUNT_FORWARD_1000', 'Does not cross the hundred: says 109 after 199, or 1000 after 199.', '{"question":"Count on: 197, 198, 199, __","wrong_answer":"1000","correct_answer":"200"}'::jsonb, 'Adds a zero or a one as when crossing a ten, without seeing the hundreds digit change.', 'The answer 1000 as a wrong option, with a reason that names the idea.', 'Use an abacus: 199 plus one bead makes 10 tens into a new hundred.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.WHOLE_NUMBERS.COUNT_FORWARD_1000.M_CNT_TENS_SKIPS_HUNDRED', 'MATH.G3.NUMBER.WHOLE_NUMBERS.COUNT_FORWARD_1000', 'Counting in tens past a hundred, writes 3100 or skips to 500.', '{"question":"Count on in tens: 380, 390, __","wrong_answer":"3100","correct_answer":"400"}'::jsonb, 'Writes 39 tens plus one ten as 3 then 10.', 'The answer 3100 as a wrong option, with a reason that names the idea.', 'Count in tens on a hundred square: ten tens make the next hundred.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.WHOLE_NUMBERS.COUNT_FORWARD_1000.M_CNT_REPEATS_START', 'MATH.G3.NUMBER.WHOLE_NUMBERS.COUNT_FORWARD_1000', 'Counts the starting number again when counting on.', '{"question":"Count on 3 from 456. Where do you stop?","wrong_answer":"458","correct_answer":"459"}'::jsonb, 'Says the start number as ''one''.', 'The answer 458 as a wrong option, with a reason that names the idea.', 'Put a finger on 456 and say ''one'' only on the next step.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.WHOLE_NUMBERS.COUNT_FORWARD_1000.M_CNT_ONES_INSTEAD_OF_TENS', 'MATH.G3.NUMBER.WHOLE_NUMBERS.COUNT_FORWARD_1000', 'Counts on in ones when asked to count in tens.', '{"question":"Count on in tens from 520: 520, __","wrong_answer":"521","correct_answer":"530"}'::jsonb, 'Does not hear the size of the step.', 'The answer 521 as a wrong option, with a reason that names the idea.', 'Say the step before each jump: ''add ten''.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.WHOLE_NUMBERS.COUNT_BACK_HUNDREDS.M_CB_FORWARD_INSTEAD', 'MATH.G3.NUMBER.WHOLE_NUMBERS.COUNT_BACK_HUNDREDS', 'Counts forward when asked to count back.', '{"question":"Count back in hundreds: 700, 600, __","wrong_answer":"700","correct_answer":"500"}'::jsonb, 'Treats counting as always going up.', 'The answer 700 as a wrong option, with a reason that names the idea.', 'Walk backwards along a hundreds number line as you count.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.WHOLE_NUMBERS.COUNT_BACK_HUNDREDS.M_CB_1000_TO_9000', 'MATH.G3.NUMBER.WHOLE_NUMBERS.COUNT_BACK_HUNDREDS', 'After 1,000 says 9000 or 990 instead of 900.', '{"question":"Count back in hundreds from 1,000: 1000, __","wrong_answer":"990","correct_answer":"900"}'::jsonb, 'Takes away a ten, or writes the 9 in the wrong place.', 'The answer 990 as a wrong option, with a reason that names the idea.', 'Show 1,000 as ten hundred bundles and remove one bundle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.WHOLE_NUMBERS.COUNT_BACK_HUNDREDS.M_CB_STEP_TEN', 'MATH.G3.NUMBER.WHOLE_NUMBERS.COUNT_BACK_HUNDREDS', 'Counts back in tens instead of hundreds.', '{"question":"Count back in hundreds: 400, 300, __","wrong_answer":"290","correct_answer":"200"}'::jsonb, 'Mixes the size of the step after a few numbers.', 'The answer 290 as a wrong option, with a reason that names the idea.', 'Write each step on the line: minus 100.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.WHOLE_NUMBERS.COUNT_BACK_HUNDREDS.M_CB_ZERO_AFTER_100', 'MATH.G3.NUMBER.WHOLE_NUMBERS.COUNT_BACK_HUNDREDS', 'Stops at 100 or says ''zero hundred'' and cannot say the last step.', '{"question":"Count back in hundreds: 300, 200, 100, __","wrong_answer":"00","correct_answer":"0"}'::jsonb, 'Has not met 0 as the end of a count.', 'The answer 00 as a wrong option, with a reason that names the idea.', 'Count back the bundles until none are left: zero.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HUNDREDS.M_PV_FACE_VALUE', 'MATH.G3.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HUNDREDS', 'Says a digit is worth only itself, whatever its place.', '{"question":"What is the 4 in 347 worth?","wrong_answer":"4","correct_answer":"40"}'::jsonb, 'Sees the digit, not the place.', 'The answer 4 as a wrong option, with a reason that names the idea.', 'Put 347 in a place value chart and build it with bundles.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HUNDREDS.M_PV_SKIPS_EMPTY_PLACE', 'MATH.G3.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HUNDREDS', 'Leaves out a zero when building a number with an empty place.', '{"question":"Write 3 hundreds, 0 tens and 5 ones as a number.","wrong_answer":"35","correct_answer":"305"}'::jsonb, 'Thinks nothing need be written for no tens.', 'The answer 35 as a wrong option, with a reason that names the idea.', 'Write in a three-column chart: every column gets a digit, 0 for empty.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HUNDREDS.M_PV_REVERSED_ORDER', 'MATH.G3.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HUNDREDS', 'Writes the ones first, so the digits come out reversed.', '{"question":"Write 2 hundreds, 6 tens and 8 ones as a number.","wrong_answer":"862","correct_answer":"268"}'::jsonb, 'Writes in the order the digits are found, not the order of places.', 'The answer 862 as a wrong option, with a reason that names the idea.', 'Label the chart: hundreds on the left, ones on the right.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HUNDREDS.M_PV_ADDS_DIGITS', 'MATH.G3.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HUNDREDS', 'Adds the digits together instead of placing them.', '{"question":"Write 4 hundreds, 3 tens and 2 ones as a number.","wrong_answer":"9","correct_answer":"432"}'::jsonb, 'Treats ''and'' as add the digits.', 'The answer 9 as a wrong option, with a reason that names the idea.', 'Count the bundles: 4 hundreds is 400, not 4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HUNDREDS.M_PV_LEAVES_OUT_PLACE', 'MATH.G3.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HUNDREDS', 'Leaves out one of the places, so the number has too few digits or a zero where a digit belongs.', '{"question":"Write 5 hundreds, 7 tens and 1 one as a number.","wrong_answer":"501","correct_answer":"571"}'::jsonb, 'Loses track of the middle place.', 'The answer 501 as a wrong option, with a reason that names the idea.', 'Tick each place in the chart as its digit is written.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HUNDREDS.M_PV_BIGGEST_DIGIT_WINS', 'MATH.G3.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_HUNDREDS', 'Thinks the number with the biggest digit anywhere is the greatest.', '{"question":"Which is greater, 189 or 312?","wrong_answer":"189","correct_answer":"312"}'::jsonb, 'Looks for the largest digit, 9, instead of the hundreds.', 'The answer 189 as a wrong option, with a reason that names the idea.', 'Compare the hundreds first: 1 hundred or 3 hundreds?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.WHOLE_NUMBERS.READ_SYMBOLS_1000.M_READ_ZERO_SAID', 'MATH.G3.NUMBER.WHOLE_NUMBERS.READ_SYMBOLS_1000', 'Reads the zero aloud, as ''four hundred zero six''.', '{"question":"Read 406 aloud.","wrong_answer":"four hundred zero six","correct_answer":"four hundred and six"}'::jsonb, 'Says every digit it sees.', 'The answer four hundred zero six as a wrong option, with a reason that names the idea.', 'Show 406 with bundles: no tens, so the word for tens is left out.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.WHOLE_NUMBERS.READ_SYMBOLS_1000.M_READ_DIGIT_BY_DIGIT', 'MATH.G3.NUMBER.WHOLE_NUMBERS.READ_SYMBOLS_1000', 'Reads the digits one by one, as ''two five three''.', '{"question":"Read 253 aloud.","wrong_answer":"two five three","correct_answer":"two hundred and fifty-three"}'::jsonb, 'Has not learnt to name the places while reading.', 'The answer two five three as a wrong option, with a reason that names the idea.', 'Point to each digit and say its place before reading.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.WHOLE_NUMBERS.READ_SYMBOLS_1000.M_READ_TEEN_TY', 'MATH.G3.NUMBER.WHOLE_NUMBERS.READ_SYMBOLS_1000', 'Reads a teen as a ty, as ''three hundred and forty'' for 314.', '{"question":"Read 314 aloud.","wrong_answer":"three hundred and forty","correct_answer":"three hundred and fourteen"}'::jsonb, 'Fourteen and forty sound alike.', 'The answer three hundred and forty as a wrong option, with a reason that names the idea.', 'Build 314: 1 ten and 4 ones is fourteen, 4 tens is forty.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.WHOLE_NUMBERS.READ_SYMBOLS_1000.M_READ_HUNDRED_AS_THOUSAND', 'MATH.G3.NUMBER.WHOLE_NUMBERS.READ_SYMBOLS_1000', 'Says ''thousand'' for a three-digit number.', '{"question":"Read 700 aloud.","wrong_answer":"seven thousand","correct_answer":"seven hundred"}'::jsonb, 'Thinks two zeros mean thousand.', 'The answer seven thousand as a wrong option, with a reason that names the idea.', 'Count the digits: three digits is hundreds, four digits is thousands.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.WHOLE_NUMBERS.WORDS_100.M_WORDS_FOURTY', 'MATH.G3.NUMBER.WHOLE_NUMBERS.WORDS_100', 'Spells forty as fourty.', '{"question":"Write 40 in words.","wrong_answer":"fourty","correct_answer":"forty"}'::jsonb, 'Spells it like four.', 'The answer fourty as a wrong option, with a reason that names the idea.', 'Write four, fourteen, forty in a column and circle the missing u.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.WHOLE_NUMBERS.WORDS_100.M_WORDS_TEEN_FOR_TY', 'MATH.G3.NUMBER.WHOLE_NUMBERS.WORDS_100', 'Writes a teen word for a ty number, as sixteen for 60.', '{"question":"Write 60 in words.","wrong_answer":"sixteen","correct_answer":"sixty"}'::jsonb, 'The words sound alike.', 'The answer sixteen as a wrong option, with a reason that names the idea.', 'Sixteen is 1 ten and 6; sixty is 6 tens.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.WHOLE_NUMBERS.WORDS_100.M_WORDS_REVERSED_DIGITS', 'MATH.G3.NUMBER.WHOLE_NUMBERS.WORDS_100', 'Writes the number for a word with the digits reversed, as 72 for twenty-seven.', '{"question":"Write twenty-seven as a number.","wrong_answer":"72","correct_answer":"27"}'::jsonb, 'Writes the 7 heard in ''seven'' first.', 'The answer 72 as a wrong option, with a reason that names the idea.', 'Twenty is 2 tens: write the tens digit first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.WHOLE_NUMBERS.WORDS_100.M_WORDS_JOINED_NUMBER', 'MATH.G3.NUMBER.WHOLE_NUMBERS.WORDS_100', 'Writes twenty-five as 205 or 20 5.', '{"question":"Write twenty-five as a number.","wrong_answer":"205","correct_answer":"25"}'::jsonb, 'Writes 20 then 5 side by side.', 'The answer 205 as a wrong option, with a reason that names the idea.', 'Twenty-five has 2 tens and 5 ones: two digits only.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.WHOLE_NUMBERS.PATTERNS_1000.M_PAT_ONES_FOR_TENS', 'MATH.G3.NUMBER.WHOLE_NUMBERS.PATTERNS_1000', 'Adds one each time when the pattern goes up in tens.', '{"question":"240, 250, 260, __","wrong_answer":"261","correct_answer":"270"}'::jsonb, 'Assumes every pattern goes up by one.', 'The answer 261 as a wrong option, with a reason that names the idea.', 'Find the jump between two numbers first: 250 minus 240.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.WHOLE_NUMBERS.PATTERNS_1000.M_PAT_DIRECTION', 'MATH.G3.NUMBER.WHOLE_NUMBERS.PATTERNS_1000', 'Continues a falling pattern upwards.', '{"question":"900, 800, 700, __","wrong_answer":"800","correct_answer":"600"}'::jsonb, 'Does not check whether the numbers grow or shrink.', 'The answer 800 as a wrong option, with a reason that names the idea.', 'Draw arrows between terms and write + or -.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.WHOLE_NUMBERS.PATTERNS_1000.M_PAT_FIRST_JUMP_ONLY', 'MATH.G3.NUMBER.WHOLE_NUMBERS.PATTERNS_1000', 'Uses only the first jump and misses that the jump changes or is in the middle.', '{"question":"105, 110, __, 120, 125","wrong_answer":"111","correct_answer":"115"}'::jsonb, 'Fills the gap by adding one to the number before.', 'The answer 111 as a wrong option, with a reason that names the idea.', 'Check the jump on both sides of the gap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.WHOLE_NUMBERS.PATTERNS_1000.M_PAT_CROSS_HUNDRED', 'MATH.G3.NUMBER.WHOLE_NUMBERS.PATTERNS_1000', 'Breaks the pattern when it crosses a hundred, as 480, 490, 4100.', '{"question":"470, 480, 490, __","wrong_answer":"4100","correct_answer":"500"}'::jsonb, 'Writes the tens as 10 instead of moving to the next hundred.', 'The answer 4100 as a wrong option, with a reason that names the idea.', 'Count in tens on an abacus: ten tens is one hundred.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.ADDITION.ADD_3D_2D_NO_REGROUP.M_ADD_MISALIGNED', 'MATH.G3.NUMBER.ADDITION.ADD_3D_2D_NO_REGROUP', 'Lines up the 2-digit number under the hundreds and tens instead of the tens and ones.', '{"question":"342 + 25","wrong_answer":"592","correct_answer":"367"}'::jsonb, 'Writes both numbers from the left.', 'The answer 592 as a wrong option, with a reason that names the idea.', 'Line up from the right: ones under ones.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.ADDITION.ADD_3D_2D_NO_REGROUP.M_ADD_ONLY_ONES', 'MATH.G3.NUMBER.ADDITION.ADD_3D_2D_NO_REGROUP', 'Adds the ones and copies the rest of the first number, forgetting the tens of the second.', '{"question":"531 + 46","wrong_answer":"537","correct_answer":"577"}'::jsonb, 'Stops after the ones column.', 'The answer 537 as a wrong option, with a reason that names the idea.', 'Tick each column of the smaller number as it is added.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.ADDITION.ADD_3D_2D_NO_REGROUP.M_ADD_COUNTS_ON_FROM_FIRST', 'MATH.G3.NUMBER.ADDITION.ADD_3D_2D_NO_REGROUP', 'Counts on from the first number and includes it, so the sum is one less.', '{"question":"604 + 3, counting on","wrong_answer":"606","correct_answer":"607"}'::jsonb, 'Counts 604 as ''one''.', 'The answer 606 as a wrong option, with a reason that names the idea.', 'Put a finger on 604 and count 605, 606, 607.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.ADDITION.ADD_3D_2D_NO_REGROUP.M_ADD_DIGITS_JOINED', 'MATH.G3.NUMBER.ADDITION.ADD_3D_2D_NO_REGROUP', 'Writes the two numbers side by side, as 3425 for 342 + 5.', '{"question":"342 + 5","wrong_answer":"3425","correct_answer":"347"}'::jsonb, 'Thinks ''add'' means put next to.', 'The answer 3425 as a wrong option, with a reason that names the idea.', 'Show 342 bundles and 5 straws together: count them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.ADDITION.ADD_3D_2D_REGROUP.M_ADD_FORGETS_CARRY', 'MATH.G3.NUMBER.ADDITION.ADD_3D_2D_REGROUP', 'Writes the ones digit of the sum but forgets to carry the ten.', '{"question":"347 + 28","wrong_answer":"365","correct_answer":"375"}'::jsonb, 'Does not record the ten made.', 'The answer 365 as a wrong option, with a reason that names the idea.', 'Exchange 10 ones for a ten bundle and put it in the tens.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.ADDITION.ADD_3D_2D_REGROUP.M_ADD_WRITES_BOTH_DIGITS', 'MATH.G3.NUMBER.ADDITION.ADD_3D_2D_REGROUP', 'Writes the whole 2-digit sum of a column, as 3615 for 347 + 28.', '{"question":"347 + 28","wrong_answer":"3615","correct_answer":"375"}'::jsonb, 'Does not see that a column holds one digit.', 'The answer 3615 as a wrong option, with a reason that names the idea.', 'One digit per column: exchange the ten.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.ADDITION.ADD_3D_2D_REGROUP.M_ADD_CARRY_TO_WRONG_COLUMN', 'MATH.G3.NUMBER.ADDITION.ADD_3D_2D_REGROUP', 'Carries the ten into the hundreds column.', '{"question":"256 + 37","wrong_answer":"393","correct_answer":"293"}'::jsonb, 'Puts the small 1 above the wrong digit.', 'The answer 393 as a wrong option, with a reason that names the idea.', 'Write the carried 1 directly above the tens.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.ADDITION.ADD_3D_2D_REGROUP.M_ADD_ADDS_CARRY_TWICE', 'MATH.G3.NUMBER.ADDITION.ADD_3D_2D_REGROUP', 'Adds the carried one twice, or to two columns.', '{"question":"168 + 25","wrong_answer":"203","correct_answer":"193"}'::jsonb, 'Writes the carry above two digits.', 'The answer 203 as a wrong option, with a reason that names the idea.', 'Cross out the carried digit once you have added it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.ADDITION.ADD_3D_3D_NO_REGROUP.M_ADD3_MIXES_COLUMNS', 'MATH.G3.NUMBER.ADDITION.ADD_3D_3D_NO_REGROUP', 'Adds digits across columns, such as hundreds of one number with tens of the other.', '{"question":"423 + 361","wrong_answer":"748","correct_answer":"784"}'::jsonb, 'Writes the numbers out of line.', 'The answer 748 as a wrong option, with a reason that names the idea.', 'Use squared paper: one digit in each square.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.ADDITION.ADD_3D_3D_NO_REGROUP.M_ADD3_LEFT_TO_RIGHT_SLIP', 'MATH.G3.NUMBER.ADDITION.ADD_3D_3D_NO_REGROUP', 'Adds from the left and writes the digits in the wrong order.', '{"question":"213 + 452","wrong_answer":"566","correct_answer":"665"}'::jsonb, 'Starts with the hundreds and writes from the right.', 'The answer 566 as a wrong option, with a reason that names the idea.', 'Always start with the ones on the right and write under the column.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.ADDITION.ADD_3D_3D_NO_REGROUP.M_ADD3_SUBTRACTS', 'MATH.G3.NUMBER.ADDITION.ADD_3D_3D_NO_REGROUP', 'Takes the smaller digit from the larger in a column instead of adding.', '{"question":"512 + 361","wrong_answer":"251","correct_answer":"873"}'::jsonb, 'Mixes up the + and - signs.', 'The answer 251 as a wrong option, with a reason that names the idea.', 'Circle the sign and say ''add'' before starting.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.ADDITION.ADD_3D_3D_NO_REGROUP.M_ADD3_DROPS_ZERO', 'MATH.G3.NUMBER.ADDITION.ADD_3D_3D_NO_REGROUP', 'Leaves out a zero in a column, so the sum is a 2-digit number.', '{"question":"405 + 302","wrong_answer":"77","correct_answer":"707"}'::jsonb, 'Thinks 0 + 0 means nothing to write.', 'The answer 77 as a wrong option, with a reason that names the idea.', 'Every column gets a digit, even 0.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.ADDITION.ADD_3D_3D_REGROUP.M_ADD_FORGETS_CARRY_3D', 'MATH.G3.NUMBER.ADDITION.ADD_3D_3D_REGROUP', 'Forgets to carry the ten from the ones.', '{"question":"256 + 318","wrong_answer":"564","correct_answer":"574"}'::jsonb, 'Writes the ones digit and moves on.', 'The answer 564 as a wrong option, with a reason that names the idea.', 'Exchange ten ones for one ten with bundles.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.ADDITION.ADD_3D_3D_REGROUP.M_ADD_SUBTRACTS_INSTEAD', 'MATH.G3.NUMBER.ADDITION.ADD_3D_3D_REGROUP', 'Takes away when the story says altogether.', '{"question":"A shop sells 245 eggs on Monday and 136 on Tuesday. How many altogether?","wrong_answer":"109","correct_answer":"381"}'::jsonb, 'Takes the smaller from the larger.', 'The answer 109 as a wrong option, with a reason that names the idea.', 'Altogether means put together: add.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.ADDITION.ADD_3D_3D_REGROUP.M_ADD_CARRIES_TWICE', 'MATH.G3.NUMBER.ADDITION.ADD_3D_3D_REGROUP', 'Carries a ten that was not made, or carries twice.', '{"question":"251 + 327","wrong_answer":"588","correct_answer":"578"}'::jsonb, 'Carries out of habit.', 'The answer 588 as a wrong option, with a reason that names the idea.', 'Carry only when a column makes 10 or more.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
