INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.MULTIPLICATION.MULT_1D_BY_1D.M_MULT_NEIGHBOUR_FACT', 'MATH.G3.NUMBER.MULTIPLICATION.MULT_1D_BY_1D', 'Gives a neighbouring fact from the chart, as 7 x 8 = 54.', '{"question":"7 x 8","wrong_answer":"54","correct_answer":"56"}'::jsonb, 'Reads the chart one square off.', 'The answer 54 as a wrong option, with a reason that names the idea.', 'Run fingers along the row and down the column to meet.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.MULTIPLICATION.MULT_1D_BY_1D.M_MULT_ZERO_IS_NUMBER', 'MATH.G3.NUMBER.MULTIPLICATION.MULT_1D_BY_1D', 'Says a number times 0 or 1 is the other number plus or the number itself wrongly, as 5 x 0 = 5.', '{"question":"5 x 0","wrong_answer":"5","correct_answer":"0"}'::jsonb, 'Thinks multiplying never makes a number vanish.', 'The answer 5 as a wrong option, with a reason that names the idea.', 'Five groups with nothing in each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.MULTIPLICATION.MULT_BY_10.M_M10_ADDS_TEN', 'MATH.G3.NUMBER.MULTIPLICATION.MULT_BY_10', 'Adds 10 instead of multiplying by 10.', '{"question":"6 x 10","wrong_answer":"16","correct_answer":"60"}'::jsonb, 'Treats x 10 as + 10.', 'The answer 16 as a wrong option, with a reason that names the idea.', '6 bundles of ten straws: count in tens.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.MULTIPLICATION.MULT_BY_10.M_M10_ZERO_IN_FRONT', 'MATH.G3.NUMBER.MULTIPLICATION.MULT_BY_10', 'Writes the zero before the digit, as 06.', '{"question":"4 x 10","wrong_answer":"04","correct_answer":"40"}'::jsonb, 'Knows a zero is involved but not where.', 'The answer 04 as a wrong option, with a reason that names the idea.', 'Write the tens digit in the tens place, 0 in the ones.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.MULTIPLICATION.MULT_BY_10.M_M10_HUNDRED', 'MATH.G3.NUMBER.MULTIPLICATION.MULT_BY_10', 'Writes two zeros, as 700 for 7 x 10.', '{"question":"7 x 10","wrong_answer":"700","correct_answer":"70"}'::jsonb, 'Mixes x 10 with x 100.', 'The answer 700 as a wrong option, with a reason that names the idea.', 'Count 7 bundles of ten aloud: 10, 20 ... 70.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.MULTIPLICATION.MULT_BY_10.M_M10_TEN_FOR_EACH_DIGIT', 'MATH.G3.NUMBER.MULTIPLICATION.MULT_BY_10', 'Says 10 x 1 is 1 or 10 x 10 is 20.', '{"question":"1 x 10","wrong_answer":"1","correct_answer":"10"}'::jsonb, 'Thinks one group changes nothing to 1.', 'The answer 1 as a wrong option, with a reason that names the idea.', 'One bundle of ten is ten.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.DIVISION.DIV_REPEATED_SUBTRACTION.M_DREP_ANSWER_LAST_NUMBER', 'MATH.G3.NUMBER.DIVISION.DIV_REPEATED_SUBTRACTION', 'Gives the last number reached instead of how many times 5 was taken.', '{"question":"20 - 5 - 5 - 5 - 5 = 0. How many fives were taken?","wrong_answer":"0","correct_answer":"4"}'::jsonb, 'Reads the result of the subtraction as the answer.', 'The answer 0 as a wrong option, with a reason that names the idea.', 'Ring each 5 that is taken and count the rings.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.DIVISION.DIV_REPEATED_SUBTRACTION.M_DREP_STOPS_EARLY', 'MATH.G3.NUMBER.DIVISION.DIV_REPEATED_SUBTRACTION', 'Stops before all are taken away.', '{"question":"Take 4 at a time from 16. How many times?","wrong_answer":"3","correct_answer":"4"}'::jsonb, 'Loses track of what is left.', 'The answer 3 as a wrong option, with a reason that names the idea.', 'Write what is left after each take: 12, 8, 4, 0.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.DIVISION.DIV_REPEATED_SUBTRACTION.M_DREP_SUBTRACTS_ONCE', 'MATH.G3.NUMBER.DIVISION.DIV_REPEATED_SUBTRACTION', 'Takes the group away once and gives what is left.', '{"question":"40 maize cobs are fed 5 a day. For how many days?","wrong_answer":"35","correct_answer":"8"}'::jsonb, 'Does one subtraction and stops.', 'The answer 35 as a wrong option, with a reason that names the idea.', 'Keep taking 5 until nothing is left; count the days.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.DIVISION.DIV_REPEATED_SUBTRACTION.M_DREP_WRONG_GROUP', 'MATH.G3.NUMBER.DIVISION.DIV_REPEATED_SUBTRACTION', 'Takes away a different number each time.', '{"question":"Take 5 at a time from 25: 25, 20, 16, ...","wrong_answer":"20, 16","correct_answer":"20, 15, 10, 5, 0"}'::jsonb, 'Slips in the subtraction.', 'The answer 20, 16 as a wrong option, with a reason that names the idea.', 'Count back 5 on a number line each time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.DIVISION.DIV_2D_BY_1D.M_DIV_SUBTRACTS_ONCE', 'MATH.G3.NUMBER.DIVISION.DIV_2D_BY_1D', 'Takes one group away and gives what is left.', '{"question":"A rope 24 metres long is cut into pieces of 4 metres. How many pieces?","wrong_answer":"20","correct_answer":"6"}'::jsonb, 'Sees one cut, not all the pieces.', 'The answer 20 as a wrong option, with a reason that names the idea.', 'Draw the rope and mark every 4 metres.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.DIVISION.DIV_2D_BY_1D.M_DIV_GIVES_GROUP_SIZE', 'MATH.G3.NUMBER.DIVISION.DIV_2D_BY_1D', 'Gives the size of one group instead of the number of groups.', '{"question":"35 learners sit 5 at each table. How many tables?","wrong_answer":"5","correct_answer":"7"}'::jsonb, 'Repeats the number in the question.', 'The answer 5 as a wrong option, with a reason that names the idea.', 'Ask: groups of what, and how many groups?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.DIVISION.DIV_2D_BY_1D.M_DIV_ONE_EXTRA', 'MATH.G3.NUMBER.DIVISION.DIV_2D_BY_1D', 'Gives one more than the answer from the table.', '{"question":"42 ÷ 6","wrong_answer":"8","correct_answer":"7"}'::jsonb, 'Reads the next fact in the table.', 'The answer 8 as a wrong option, with a reason that names the idea.', 'Check: 6 x 8 = 48, not 42.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.DIVISION.DIV_2D_BY_1D.M_DIV_REVERSED', 'MATH.G3.NUMBER.DIVISION.DIV_2D_BY_1D', 'Divides the smaller number by the larger, or says 6 ÷ 42.', '{"question":"Share 42 sweets among 6 children.","wrong_answer":"0","correct_answer":"7"}'::jsonb, 'Writes the numbers in the order of the story.', 'The answer 0 as a wrong option, with a reason that names the idea.', 'The number being shared comes first: 42 ÷ 6.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.DIVISION.DIV_BY_10.M_D10_SUBTRACTS_TEN', 'MATH.G3.NUMBER.DIVISION.DIV_BY_10', 'Takes away 10 instead of dividing by 10.', '{"question":"70 ÷ 10","wrong_answer":"60","correct_answer":"7"}'::jsonb, 'Treats ÷ 10 as - 10.', 'The answer 60 as a wrong option, with a reason that names the idea.', '70 straws in bundles of ten: count the bundles.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.DIVISION.DIV_BY_10.M_D10_KEEPS_ZERO', 'MATH.G3.NUMBER.DIVISION.DIV_BY_10', 'Writes the answer with the zero, as 70 ÷ 10 = 70 or 07.', '{"question":"50 ÷ 10","wrong_answer":"05","correct_answer":"5"}'::jsonb, 'Thinks the zero moves to the front.', 'The answer 05 as a wrong option, with a reason that names the idea.', 'Count tens: 50 is 5 tens.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.DIVISION.DIV_BY_10.M_D10_MULTIPLIES', 'MATH.G3.NUMBER.DIVISION.DIV_BY_10', 'Multiplies by 10 instead of dividing.', '{"question":"30 ÷ 10","wrong_answer":"300","correct_answer":"3"}'::jsonb, 'Mixes the signs.', 'The answer 300 as a wrong option, with a reason that names the idea.', 'Dividing makes the number smaller here.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.DIVISION.DIV_BY_10.M_D10_WRONG_TENS', 'MATH.G3.NUMBER.DIVISION.DIV_BY_10', 'Gives the tens digit of a neighbouring number.', '{"question":"90 pencils are packed 10 in a packet. How many packets?","wrong_answer":"10","correct_answer":"9"}'::jsonb, 'Counts the packet of ten as one more.', 'The answer 10 as a wrong option, with a reason that names the idea.', 'Count in tens to 90 on fingers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.FRACTIONS.FRACTION_OF_WHOLE.M_FRAC_UNEQUAL_PARTS', 'MATH.G3.NUMBER.FRACTIONS.FRACTION_OF_WHOLE', 'Calls any one of two parts a half, even when the parts are not equal.', '{"question":"A chapati is torn into a big piece and a small piece. Is the small piece a half?","wrong_answer":"yes","correct_answer":"no"}'::jsonb, 'Thinks a half means one of two pieces.', 'The answer yes as a wrong option, with a reason that names the idea.', 'Fold paper: halves match exactly when folded.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.FRACTIONS.FRACTION_OF_WHOLE.M_FRAC_COUNTS_PARTS_LEFT', 'MATH.G3.NUMBER.FRACTIONS.FRACTION_OF_WHOLE', 'Names the fraction from the parts not shaded.', '{"question":"A square in 4 equal parts has 1 part shaded. What fraction is shaded?","wrong_answer":"3/4","correct_answer":"1/4"}'::jsonb, 'Counts the other parts.', 'The answer 3/4 as a wrong option, with a reason that names the idea.', 'Point at the shaded part and say ''one of four''.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.FRACTIONS.FRACTION_OF_WHOLE.M_FRAC_WRITES_PARTS_AS_DENOM', 'MATH.G3.NUMBER.FRACTIONS.FRACTION_OF_WHOLE', 'Writes the number of parts on top, as 4/1 for a quarter.', '{"question":"Write one quarter as a fraction.","wrong_answer":"4/1","correct_answer":"1/4"}'::jsonb, 'Does not know which number goes where.', 'The answer 4/1 as a wrong option, with a reason that names the idea.', 'The bottom number tells how many equal parts the whole has.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.FRACTIONS.FRACTION_OF_WHOLE.M_FRAC_EIGHTH_AS_HALF_OF_QUARTER_CONFUSED', 'MATH.G3.NUMBER.FRACTIONS.FRACTION_OF_WHOLE', 'Folds a quarter once more and calls it a sixth or a fifth.', '{"question":"A paper folded into quarters is folded once more. What is one part called?","wrong_answer":"1/6","correct_answer":"1/8"}'::jsonb, 'Adds 2 parts instead of doubling.', 'The answer 1/6 as a wrong option, with a reason that names the idea.', 'Unfold and count the parts: 8.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.FRACTIONS.COMPARE_UNIT_FRACTIONS.M_FRAC_MORE_PIECES_BIGGER', 'MATH.G3.NUMBER.FRACTIONS.COMPARE_UNIT_FRACTIONS', 'Thinks an eighth is bigger than a half because 8 is bigger than 2.', '{"question":"Which is bigger, 1/8 or 1/2 of the same cake?","wrong_answer":"1/8","correct_answer":"1/2"}'::jsonb, 'Compares the bottom numbers as whole numbers.', 'The answer 1/8 as a wrong option, with a reason that names the idea.', 'Cut two same cakes into 2 and 8: compare one piece of each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.FRACTIONS.COMPARE_UNIT_FRACTIONS.M_FRAC_DIFFERENT_WHOLES', 'MATH.G3.NUMBER.FRACTIONS.COMPARE_UNIT_FRACTIONS', 'Compares parts of wholes of different sizes.', '{"question":"A quarter of a big watermelon and a half of a small orange. Is the half always bigger?","wrong_answer":"yes","correct_answer":"no"}'::jsonb, 'Forgets the wholes must be the same.', 'The answer yes as a wrong option, with a reason that names the idea.', 'Compare halves and quarters of the same thing only.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.FRACTIONS.COMPARE_UNIT_FRACTIONS.M_FRAC_ORDER_BY_NUMBER', 'MATH.G3.NUMBER.FRACTIONS.COMPARE_UNIT_FRACTIONS', 'Orders the fractions as 1/2, 1/4, 1/8 from smallest to biggest.', '{"question":"Order from smallest to biggest: 1/2, 1/8, 1/4.","wrong_answer":"1/2, 1/4, 1/8","correct_answer":"1/8, 1/4, 1/2"}'::jsonb, 'Orders by the bottom number.', 'The answer 1/2, 1/4, 1/8 as a wrong option, with a reason that names the idea.', 'Draw the three on same-size strips.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.FRACTIONS.COMPARE_UNIT_FRACTIONS.M_FRAC_QUARTER_IS_HALF_OF_EIGHTH', 'MATH.G3.NUMBER.FRACTIONS.COMPARE_UNIT_FRACTIONS', 'Says a quarter is half of an eighth.', '{"question":"How many eighths make a quarter?","wrong_answer":"half","correct_answer":"2"}'::jsonb, 'Reverses the relation.', 'The answer half as a wrong option, with a reason that names the idea.', 'Fold a quarter strip in two.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.FRACTIONS.FRACTION_OF_GROUP.M_FGRP_ANSWER_IS_DENOM', 'MATH.G3.NUMBER.FRACTIONS.FRACTION_OF_GROUP', 'Gives the bottom number as the answer.', '{"question":"What is 1/4 of 12 oranges?","wrong_answer":"4","correct_answer":"3"}'::jsonb, 'Sees 4 and writes it.', 'The answer 4 as a wrong option, with a reason that names the idea.', 'Share 12 counters into 4 plates and count one plate.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.FRACTIONS.FRACTION_OF_GROUP.M_FGRP_SUBTRACTS', 'MATH.G3.NUMBER.FRACTIONS.FRACTION_OF_GROUP', 'Takes the denominator away from the group.', '{"question":"What is 1/2 of 10 sweets?","wrong_answer":"8","correct_answer":"5"}'::jsonb, 'Takes away 2 because of the 2.', 'The answer 8 as a wrong option, with a reason that names the idea.', 'Share into 2 equal groups.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.FRACTIONS.FRACTION_OF_GROUP.M_FGRP_UNEQUAL_SHARE', 'MATH.G3.NUMBER.FRACTIONS.FRACTION_OF_GROUP', 'Shares into groups that are not equal and calls one a quarter.', '{"question":"12 mangoes are put in heaps of 4, 3, 3 and 2. Is the heap of 3 a quarter?","wrong_answer":"yes","correct_answer":"no"}'::jsonb, 'Thinks any of 4 heaps is a quarter.', 'The answer yes as a wrong option, with a reason that names the idea.', 'Each quarter must have the same number.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.NUMBER.FRACTIONS.FRACTION_OF_GROUP.M_FGRP_MULTIPLIES', 'MATH.G3.NUMBER.FRACTIONS.FRACTION_OF_GROUP', 'Multiplies the group by the denominator.', '{"question":"What is 1/8 of 16 bottle tops?","wrong_answer":"128","correct_answer":"2"}'::jsonb, 'Uses the operation that makes numbers bigger.', 'The answer 128 as a wrong option, with a reason that names the idea.', 'A part of a group is smaller than the group.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.LENGTH.MEASURE_METRES.M_LEN_GAPS_OVERLAPS', 'MATH.G3.MEASUR.LENGTH.MEASURE_METRES', 'Leaves gaps or overlaps between metre sticks, so the count is wrong.', '{"question":"A path is measured by laying a metre stick 5 times with gaps between. Is it 5 m long?","wrong_answer":"yes","correct_answer":"no, it is longer"}'::jsonb, 'Does not move the stick exactly to the end mark.', 'The answer yes as a wrong option, with a reason that names the idea.', 'Mark the end of the stick with chalk before moving it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.LENGTH.MEASURE_METRES.M_LEN_NO_UNIT', 'MATH.G3.MEASUR.LENGTH.MEASURE_METRES', 'Writes the number without the unit.', '{"question":"The table is 2 metre sticks long. Write its length.","wrong_answer":"2","correct_answer":"2 m"}'::jsonb, 'Thinks the number is enough.', 'The answer 2 as a wrong option, with a reason that names the idea.', 'Always say what was counted: 2 metres.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.LENGTH.MEASURE_METRES.M_LEN_COUNTS_KNOTS', 'MATH.G3.MEASUR.LENGTH.MEASURE_METRES', 'Counts the knots on the string instead of the spaces between them.', '{"question":"A string has a knot at the start and one every metre. 6 knots reach the wall. How far is it?","wrong_answer":"6 m","correct_answer":"5 m"}'::jsonb, 'Counts the marks, not the metres.', 'The answer 6 m as a wrong option, with a reason that names the idea.', 'Count the spaces between knots.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.LENGTH.MEASURE_METRES.M_LEN_START_NOT_AT_END', 'MATH.G3.MEASUR.LENGTH.MEASURE_METRES', 'Starts measuring from a point that is not the end of the object.', '{"question":"A metre stick starts 1 metre in from the end of a 7 m wall. 6 sticks reach the other end. How long is the wall?","wrong_answer":"6 m","correct_answer":"7 m"}'::jsonb, 'Does not line the start up with the end.', 'The answer 6 m as a wrong option, with a reason that names the idea.', 'Put the end of the stick at the very end of the wall.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.LENGTH.ADD_METRES.M_LADD_ONLY_TWO_SIDES', 'MATH.G3.MEASUR.LENGTH.ADD_METRES', 'Adds only two walls when asked for all four.', '{"question":"A room is 8 m long and 6 m wide. What is the total length of all four walls?","wrong_answer":"14 m","correct_answer":"28 m"}'::jsonb, 'Adds the two numbers given.', 'The answer 14 m as a wrong option, with a reason that names the idea.', 'Draw the room and write a length on every wall.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.LENGTH.ADD_METRES.M_LADD_SUBTRACTS', 'MATH.G3.MEASUR.LENGTH.ADD_METRES', 'Subtracts when the story joins two pieces.', '{"question":"Two ropes of 9 m and 7 m are tied together. How long is the new rope?","wrong_answer":"2 m","correct_answer":"16 m"}'::jsonb, 'Sees two numbers and takes the smaller away.', 'The answer 2 m as a wrong option, with a reason that names the idea.', 'Joining makes it longer: add.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.LENGTH.ADD_METRES.M_LADD_CARRY', 'MATH.G3.MEASUR.LENGTH.ADD_METRES', 'Forgets to carry when adding lengths.', '{"question":"45 m + 38 m","wrong_answer":"73 m","correct_answer":"83 m"}'::jsonb, 'Slips in the regrouping.', 'The answer 73 m as a wrong option, with a reason that names the idea.', 'Add as with numbers: ones first, carry the ten.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.LENGTH.ADD_METRES.M_LADD_UNIT_LOST', 'MATH.G3.MEASUR.LENGTH.ADD_METRES', 'Writes the total without the unit or with a different unit.', '{"question":"6 m + 4 m","wrong_answer":"10","correct_answer":"10 m"}'::jsonb, 'Drops the unit while adding.', 'The answer 10 as a wrong option, with a reason that names the idea.', 'Write m after the answer every time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.LENGTH.SUBTRACT_METRES.M_LSUB_ADDS', 'MATH.G3.MEASUR.LENGTH.SUBTRACT_METRES', 'Adds when asked how much longer.', '{"question":"The chalkboard is 4 m and the table 2 m. How much longer is the chalkboard?","wrong_answer":"6 m","correct_answer":"2 m"}'::jsonb, 'Reads ''longer'' as add.', 'The answer 6 m as a wrong option, with a reason that names the idea.', 'Line the two up: the extra bit is the difference.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.LENGTH.SUBTRACT_METRES.M_LSUB_SMALLER_FROM_LARGER', 'MATH.G3.MEASUR.LENGTH.SUBTRACT_METRES', 'Takes the smaller digit from the larger in each column.', '{"question":"52 m - 17 m","wrong_answer":"45 m","correct_answer":"35 m"}'::jsonb, 'Same column error as with numbers.', 'The answer 45 m as a wrong option, with a reason that names the idea.', 'Open a ten when the top digit is smaller.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.LENGTH.SUBTRACT_METRES.M_LSUB_GIVES_PIECE_CUT', 'MATH.G3.MEASUR.LENGTH.SUBTRACT_METRES', 'Gives the piece cut off instead of what is left.', '{"question":"A 10 m rope has 3 m cut off. How much is left?","wrong_answer":"3 m","correct_answer":"7 m"}'::jsonb, 'Repeats a number from the story.', 'The answer 3 m as a wrong option, with a reason that names the idea.', 'Draw the rope, cross off 3 m, measure the rest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.LENGTH.SUBTRACT_METRES.M_LSUB_ORDER', 'MATH.G3.MEASUR.LENGTH.SUBTRACT_METRES', 'Takes the larger from the smaller and writes 0 or a wrong digit.', '{"question":"How much shorter is a 5 m rope than a 9 m rope?","wrong_answer":"0 m","correct_answer":"4 m"}'::jsonb, 'Writes the numbers in the order of the story.', 'The answer 0 m as a wrong option, with a reason that names the idea.', 'Always take the shorter from the longer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.LENGTH.ESTIMATE_METRES.M_LEST_WILD_GUESS', 'MATH.G3.MEASUR.LENGTH.ESTIMATE_METRES', 'Gives an estimate far from the real length, with no benchmark.', '{"question":"About how long is a classroom?","wrong_answer":"100 m","correct_answer":"about 8 m"}'::jsonb, 'Has no sense of how long a metre is.', 'The answer 100 m as a wrong option, with a reason that names the idea.', 'Take big steps: each is about a metre.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.LENGTH.ESTIMATE_METRES.M_LEST_WRONG_UNIT', 'MATH.G3.MEASUR.LENGTH.ESTIMATE_METRES', 'Estimates in a unit that does not fit, such as 2 m for a pencil.', '{"question":"Which is about 1 m long?","wrong_answer":"a pencil","correct_answer":"a door''s width"}'::jsonb, 'Has not linked the metre to real objects.', 'The answer a pencil as a wrong option, with a reason that names the idea.', 'Hold a metre stick next to things.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.LENGTH.ESTIMATE_METRES.M_LEST_MUST_BE_EXACT', 'MATH.G3.MEASUR.LENGTH.ESTIMATE_METRES', 'Thinks an estimate is wrong if it is not exactly the measure.', '{"question":"Juma estimated 6 m; the measure was 7 m. Was his estimate bad?","wrong_answer":"yes","correct_answer":"no, it was close"}'::jsonb, 'Thinks an estimate must be exact.', 'The answer yes as a wrong option, with a reason that names the idea.', 'An estimate is a sensible guess; close is good.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.LENGTH.ESTIMATE_METRES.M_LEST_STEPS_NOT_METRES', 'MATH.G3.MEASUR.LENGTH.ESTIMATE_METRES', 'Gives the number of small steps as metres.', '{"question":"Wanjiru takes 20 small steps across a room. About how many metres is it?","wrong_answer":"20 m","correct_answer":"about 10 m"}'::jsonb, 'Uses any step as a metre.', 'The answer 20 m as a wrong option, with a reason that names the idea.', 'A small step is about half a metre; use big steps.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.MASS.MEASURE_KG.M_MASS_HIGH_SIDE_HEAVY', 'MATH.G3.MEASUR.MASS.MEASURE_KG', 'Thinks the side of the balance that goes up is heavier.', '{"question":"On a beam balance, the bag goes up and the 3 kg masses go down. Which is heavier?","wrong_answer":"the bag","correct_answer":"the 3 kg masses"}'::jsonb, 'Links ''up'' with ''more''.', 'The answer the bag as a wrong option, with a reason that names the idea.', 'Press each pan with your hand: the heavier side goes down.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.MASS.MEASURE_KG.M_MASS_BIGGER_IS_HEAVIER', 'MATH.G3.MEASUR.MASS.MEASURE_KG', 'Thinks a bigger object is always heavier.', '{"question":"A big pillow and a small stone balance at 1 kg each. Is the pillow heavier?","wrong_answer":"yes","correct_answer":"no, they are the same"}'::jsonb, 'Judges mass by size.', 'The answer yes as a wrong option, with a reason that names the idea.', 'Weigh a big light thing and a small heavy thing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.MASS.MEASURE_KG.M_MASS_NOT_LEVEL', 'MATH.G3.MEASUR.MASS.MEASURE_KG', 'Reads the mass before the beam is level.', '{"question":"A balance tips down on the mass side with 4 kg. Is the object 4 kg?","wrong_answer":"yes","correct_answer":"no, less than 4 kg"}'::jsonb, 'Reads the masses on the pan at any point.', 'The answer yes as a wrong option, with a reason that names the idea.', 'Only read when the beam is level.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.MASS.MEASURE_KG.M_MASS_COUNTS_PANS', 'MATH.G3.MEASUR.MASS.MEASURE_KG', 'Counts the number of objects instead of the kilogram masses.', '{"question":"3 mangoes balance two 1 kg masses. What is their mass?","wrong_answer":"3 kg","correct_answer":"2 kg"}'::jsonb, 'Counts what is on the wrong pan.', 'The answer 3 kg as a wrong option, with a reason that names the idea.', 'Count the 1 kg masses only.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.MASS.ADD_KG.M_KADD_SUBTRACTS', 'MATH.G3.MEASUR.MASS.ADD_KG', 'Subtracts when the story asks for the total.', '{"question":"A basket holds 4 kg of potatoes and 3 kg of onions. What is the total mass?","wrong_answer":"1 kg","correct_answer":"7 kg"}'::jsonb, 'Takes away because one is smaller.', 'The answer 1 kg as a wrong option, with a reason that names the idea.', 'Total means put together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.MASS.ADD_KG.M_KADD_COUNTS_ITEMS', 'MATH.G3.MEASUR.MASS.ADD_KG', 'Counts the number of items instead of adding their masses.', '{"question":"Two bags: 5 kg and 2 kg. What is their mass together?","wrong_answer":"2 kg","correct_answer":"7 kg"}'::jsonb, 'Counts bags.', 'The answer 2 kg as a wrong option, with a reason that names the idea.', 'Add the masses written on the bags.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.MASS.ADD_KG.M_KADD_CARRY', 'MATH.G3.MEASUR.MASS.ADD_KG', 'Forgets the carry when adding masses.', '{"question":"48 kg + 27 kg","wrong_answer":"65 kg","correct_answer":"75 kg"}'::jsonb, 'Regrouping slip.', 'The answer 65 kg as a wrong option, with a reason that names the idea.', 'Carry the ten from the ones.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.MASS.ADD_KG.M_KADD_NO_UNIT', 'MATH.G3.MEASUR.MASS.ADD_KG', 'Leaves out kg in the answer.', '{"question":"3 kg + 2 kg","wrong_answer":"5","correct_answer":"5 kg"}'::jsonb, 'Thinks only the number matters.', 'The answer 5 as a wrong option, with a reason that names the idea.', 'Write kg after the answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.MASS.SUBTRACT_KG.M_KSUB_ADDS_HEAVIER', 'MATH.G3.MEASUR.MASS.SUBTRACT_KG', 'Adds when asked how much heavier.', '{"question":"A bag of maize is 9 kg and a bag of beans 4 kg. How much heavier is the maize?","wrong_answer":"13 kg","correct_answer":"5 kg"}'::jsonb, '''Heavier'' sounds like more.', 'The answer 13 kg as a wrong option, with a reason that names the idea.', 'Put them on a balance: the difference is the extra.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.MASS.SUBTRACT_KG.M_KSUB_SMALLER_FROM_LARGER', 'MATH.G3.MEASUR.MASS.SUBTRACT_KG', 'Takes the smaller digit from the larger in each column.', '{"question":"43 kg - 18 kg","wrong_answer":"35 kg","correct_answer":"25 kg"}'::jsonb, 'Column error.', 'The answer 35 kg as a wrong option, with a reason that names the idea.', 'Open a ten.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.MASS.SUBTRACT_KG.M_KSUB_GIVES_USED', 'MATH.G3.MEASUR.MASS.SUBTRACT_KG', 'Gives the amount used instead of what is left.', '{"question":"A 10 kg bag of rice has 4 kg used. How much is left?","wrong_answer":"4 kg","correct_answer":"6 kg"}'::jsonb, 'Repeats a number from the story.', 'The answer 4 kg as a wrong option, with a reason that names the idea.', 'Draw the bag and cross off what is used.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.MASS.SUBTRACT_KG.M_KSUB_ORDER', 'MATH.G3.MEASUR.MASS.SUBTRACT_KG', 'Takes the larger from the smaller.', '{"question":"How much lighter is 3 kg than 8 kg?","wrong_answer":"0 kg","correct_answer":"5 kg"}'::jsonb, 'Follows the order of the words.', 'The answer 0 kg as a wrong option, with a reason that names the idea.', 'Take the lighter from the heavier.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.MASS.ESTIMATE_KG.M_KEST_SIZE_GUESS', 'MATH.G3.MEASUR.MASS.ESTIMATE_KG', 'Estimates mass from size only.', '{"question":"About how heavy is a big empty box?","wrong_answer":"5 kg","correct_answer":"less than 1 kg"}'::jsonb, 'Thinks big means heavy.', 'The answer 5 kg as a wrong option, with a reason that names the idea.', 'Hold it and a 1 kg mass.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.MASS.ESTIMATE_KG.M_KEST_NO_BENCHMARK', 'MATH.G3.MEASUR.MASS.ESTIMATE_KG', 'Gives a wild estimate such as 100 kg for a school bag.', '{"question":"About how heavy is a school bag?","wrong_answer":"100 kg","correct_answer":"about 3 kg"}'::jsonb, 'Has no feel for a kilogram.', 'The answer 100 kg as a wrong option, with a reason that names the idea.', 'Lift a 1 kg bag of flour and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.MASS.ESTIMATE_KG.M_KEST_MUST_BE_EXACT', 'MATH.G3.MEASUR.MASS.ESTIMATE_KG', 'Thinks an estimate must equal the measure.', '{"question":"Achieng estimated 4 kg; the balance showed 5 kg. Was it a good estimate?","wrong_answer":"no","correct_answer":"yes, close"}'::jsonb, 'Thinks an estimate is a test of being exact.', 'The answer no as a wrong option, with a reason that names the idea.', 'Close is good.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.MASS.ESTIMATE_KG.M_KEST_MORE_LESS_SWAP', 'MATH.G3.MEASUR.MASS.ESTIMATE_KG', 'Says an item is more than 5 kg when it is lighter, mixing more and less.', '{"question":"Is a pencil more or less than 5 kg?","wrong_answer":"more","correct_answer":"less"}'::jsonb, 'Mixes the words more and less.', 'The answer more as a wrong option, with a reason that names the idea.', 'Hold both: the lighter is less.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.CAPACITY.MEASURE_LITRES.M_CAP_TALLER_HOLDS_MORE', 'MATH.G3.MEASUR.CAPACITY.MEASURE_LITRES', 'Thinks the taller container always holds more.', '{"question":"A tall thin bottle and a short wide basin both hold 3 l. Does the bottle hold more?","wrong_answer":"yes","correct_answer":"no, the same"}'::jsonb, 'Judges capacity by height only.', 'The answer yes as a wrong option, with a reason that names the idea.', 'Pour one into the other and see.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.CAPACITY.MEASURE_LITRES.M_CAP_PART_FILLS_COUNTED', 'MATH.G3.MEASUR.CAPACITY.MEASURE_LITRES', 'Counts a litre container that was not filled to the top as a full litre.', '{"question":"A jug is filled 4 times, the last time only half full. How many full litres?","wrong_answer":"4","correct_answer":"3 full litres and a half"}'::jsonb, 'Counts every pour.', 'The answer 4 as a wrong option, with a reason that names the idea.', 'Fill to the line each time; count only full ones.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.CAPACITY.MEASURE_LITRES.M_CAP_COUNTS_POURS_WRONG_CONTAINER', 'MATH.G3.MEASUR.CAPACITY.MEASURE_LITRES', 'Counts the pours of a cup as litres.', '{"question":"A bucket takes 10 cups or 2 litre jugs to fill. How many litres does it hold?","wrong_answer":"10 l","correct_answer":"2 l"}'::jsonb, 'Counts the wrong container.', 'The answer 10 l as a wrong option, with a reason that names the idea.', 'Only the 1-litre container counts litres.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.CAPACITY.MEASURE_LITRES.M_CAP_NO_UNIT', 'MATH.G3.MEASUR.CAPACITY.MEASURE_LITRES', 'Writes the number without l.', '{"question":"A basin holds 5 litre fills. Write its capacity.","wrong_answer":"5","correct_answer":"5 l"}'::jsonb, 'Drops the unit.', 'The answer 5 as a wrong option, with a reason that names the idea.', 'Say it: 5 litres.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.CAPACITY.ADD_LITRES.M_CADD_SUBTRACTS', 'MATH.G3.MEASUR.CAPACITY.ADD_LITRES', 'Subtracts when the story asks for the total.', '{"question":"A cow gives 5 l in the morning and 3 l in the evening. How much milk in all?","wrong_answer":"2 l","correct_answer":"8 l"}'::jsonb, 'Takes the smaller away.', 'The answer 2 l as a wrong option, with a reason that names the idea.', 'In all means put together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.CAPACITY.ADD_LITRES.M_CAP_ADDS_COUNT_TO_LITRES', 'MATH.G3.MEASUR.CAPACITY.ADD_LITRES', 'Adds the number of containers to the litres in one, instead of adding the litres again for each.', '{"question":"A bucket holds 5 l. 4 full buckets are poured into a tank. How many litres?","wrong_answer":"9 l","correct_answer":"20 l"}'::jsonb, 'Sees two numbers and adds them.', 'The answer 9 l as a wrong option, with a reason that names the idea.', 'Write 5 l for each bucket and add: 5 + 5 + 5 + 5.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.CAPACITY.ADD_LITRES.M_CADD_ONE_CONTAINER_SHORT', 'MATH.G3.MEASUR.CAPACITY.ADD_LITRES', 'Adds the same amount one time too few or too many.', '{"question":"3 jerrycans of 10 l are poured into a drum. How many litres?","wrong_answer":"20 l","correct_answer":"30 l"}'::jsonb, 'Loses count of the containers.', 'The answer 20 l as a wrong option, with a reason that names the idea.', 'Tick each container as you add it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.CAPACITY.ADD_LITRES.M_CADD_CARRY', 'MATH.G3.MEASUR.CAPACITY.ADD_LITRES', 'Forgets the carry.', '{"question":"26 l + 17 l","wrong_answer":"33 l","correct_answer":"43 l"}'::jsonb, 'Regrouping slip.', 'The answer 33 l as a wrong option, with a reason that names the idea.', '6 + 7 = 13: carry the ten.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.CAPACITY.SUBTRACT_LITRES.M_CSUB_GIVES_USED', 'MATH.G3.MEASUR.CAPACITY.SUBTRACT_LITRES', 'Gives what was used instead of what is left.', '{"question":"A 20 l jerrycan has 8 l used for cooking. How much is left?","wrong_answer":"8 l","correct_answer":"12 l"}'::jsonb, 'Repeats a number.', 'The answer 8 l as a wrong option, with a reason that names the idea.', 'Draw the jerrycan and shade what is left.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.CAPACITY.SUBTRACT_LITRES.M_CSUB_ADDS', 'MATH.G3.MEASUR.CAPACITY.SUBTRACT_LITRES', 'Adds when water is poured out.', '{"question":"A tank has 50 l. 20 l are poured out. How much is in it now?","wrong_answer":"70 l","correct_answer":"30 l"}'::jsonb, 'Sees two numbers and adds.', 'The answer 70 l as a wrong option, with a reason that names the idea.', 'Pouring out makes less.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.CAPACITY.SUBTRACT_LITRES.M_CSUB_SMALLER_FROM_LARGER', 'MATH.G3.MEASUR.CAPACITY.SUBTRACT_LITRES', 'Takes the smaller digit from the larger in each column.', '{"question":"40 l - 15 l","wrong_answer":"35 l","correct_answer":"25 l"}'::jsonb, 'Column error with zero.', 'The answer 35 l as a wrong option, with a reason that names the idea.', 'Open a ten: 10 - 5.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.CAPACITY.SUBTRACT_LITRES.M_CSUB_DIFFERENCE_ORDER', 'MATH.G3.MEASUR.CAPACITY.SUBTRACT_LITRES', 'Takes the larger from the smaller.', '{"question":"How much less does a 3 l jug hold than a 5 l jug?","wrong_answer":"0 l","correct_answer":"2 l"}'::jsonb, 'Follows the order of the words.', 'The answer 0 l as a wrong option, with a reason that names the idea.', 'Bigger minus smaller.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
