INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.CAPACITY.ESTIMATE_LITRES.M_CEST_NO_BENCHMARK', 'MATH.G3.MEASUR.CAPACITY.ESTIMATE_LITRES', 'Gives a wild estimate, such as 100 l for a cup.', '{"question":"About how much does a cup hold?","wrong_answer":"100 l","correct_answer":"less than 1 l"}'::jsonb, 'Has no feel for a litre.', 'The answer 100 l as a wrong option, with a reason that names the idea.', 'Pour a cup into a litre bottle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.CAPACITY.ESTIMATE_LITRES.M_CEST_MUST_BE_EXACT', 'MATH.G3.MEASUR.CAPACITY.ESTIMATE_LITRES', 'Thinks an estimate is wrong unless it matches.', '{"question":"Baraka estimated 3 l; it held 4 l. Was he close?","wrong_answer":"no","correct_answer":"yes"}'::jsonb, 'Thinks estimates must be exact.', 'The answer no as a wrong option, with a reason that names the idea.', 'Close is good.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.CAPACITY.ESTIMATE_LITRES.M_CEST_MORE_LESS_SWAP', 'MATH.G3.MEASUR.CAPACITY.ESTIMATE_LITRES', 'Says a bucket holds less than 5 litres when it holds more.', '{"question":"Does a big bucket hold more or less than 5 l?","wrong_answer":"less","correct_answer":"more"}'::jsonb, 'Mixes more and less.', 'The answer less as a wrong option, with a reason that names the idea.', 'Count litre bottles it takes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.TIME.MINUTE_UNIT.M_MIN_NUMBER_IS_MINUTE', 'MATH.G3.MEASUR.TIME.MINUTE_UNIT', 'Thinks the minute hand on 3 means 3 minutes.', '{"question":"The minute hand points to 3. How many minutes past the hour?","wrong_answer":"3","correct_answer":"15"}'::jsonb, 'Reads the clock numbers as minutes.', 'The answer 3 as a wrong option, with a reason that names the idea.', 'Count the small marks in fives from 12.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.TIME.MINUTE_UNIT.M_MIN_100_IN_HOUR', 'MATH.G3.MEASUR.TIME.MINUTE_UNIT', 'Says there are 100 minutes in an hour.', '{"question":"How many minutes in one hour?","wrong_answer":"100","correct_answer":"60"}'::jsonb, 'Thinks time counts in hundreds like numbers.', 'The answer 100 as a wrong option, with a reason that names the idea.', 'Count the marks round the clock: 60.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.TIME.MINUTE_UNIT.M_MIN_HOUR_MIN_SAME', 'MATH.G3.MEASUR.TIME.MINUTE_UNIT', 'Treats a minute and an hour as about the same length.', '{"question":"Which takes about a minute: washing hands or a school day?","wrong_answer":"a school day","correct_answer":"washing hands"}'::jsonb, 'Has no sense of the size of the units.', 'The answer a school day as a wrong option, with a reason that names the idea.', 'Time a minute with a clock while clapping.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.TIME.MINUTE_UNIT.M_MIN_FIVE_BETWEEN_NUMBERS_ONE', 'MATH.G3.MEASUR.TIME.MINUTE_UNIT', 'Says one minute passes from one number to the next.', '{"question":"How many minutes does the minute hand take from 4 to 5?","wrong_answer":"1","correct_answer":"5"}'::jsonb, 'Thinks each number is a minute.', 'The answer 1 as a wrong option, with a reason that names the idea.', 'Count the small marks between 4 and 5.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.TIME.TELL_PAST_TO.M_TIME_HANDS_SWAPPED', 'MATH.G3.MEASUR.TIME.TELL_PAST_TO', 'Reads the long hand as the hour and the short hand as the minutes.', '{"question":"The short hand points to 3 and the long hand to 12. What time is it?","wrong_answer":"12 o''clock","correct_answer":"3 o''clock"}'::jsonb, 'Does not know which hand is which.', 'The answer 12 o''clock as a wrong option, with a reason that names the idea.', 'The long hand is the minute hand and goes all the way round every hour; the short hand shows the hour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.TIME.TELL_PAST_TO.M_TIME_PAST_TO_SWAP', 'MATH.G3.MEASUR.TIME.TELL_PAST_TO', 'Says past when the minute hand is on the left half, or to on the right half.', '{"question":"The minute hand points to 8 and the hour hand is nearly at 5. What time?","wrong_answer":"20 past 4","correct_answer":"20 to 5"}'::jsonb, 'Does not see which half of the clock the hand is in.', 'The answer 20 past 4 as a wrong option, with a reason that names the idea.', 'Draw a line from 12 to 6: the right side is past, the left side is to.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.TIME.TELL_PAST_TO.M_TIME_HOUR_FROM_NEXT_NUMBER', 'MATH.G3.MEASUR.TIME.TELL_PAST_TO', 'Names the hour the short hand is moving to when it is past the hour.', '{"question":"The short hand is just after 4 and the long hand on 2. What time?","wrong_answer":"10 past 5","correct_answer":"10 past 4"}'::jsonb, 'Reads the nearest number to the short hand.', 'The answer 10 past 5 as a wrong option, with a reason that names the idea.', 'For past, the hour is the number the short hand has just passed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.TIME.TELL_PAST_TO.M_TIME_TO_COUNTS_FROM_12', 'MATH.G3.MEASUR.TIME.TELL_PAST_TO', 'For ''to'' times, counts the minutes from 12 clockwise instead of to the 12.', '{"question":"The long hand points to 9. How many minutes to the hour?","wrong_answer":"45","correct_answer":"15"}'::jsonb, 'Counts forward from 12.', 'The answer 45 as a wrong option, with a reason that names the idea.', 'For ''to'', count from the minute hand on to 12.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.TIME.READ_DIGITAL.M_DIG_READS_AS_NUMBER', 'MATH.G3.MEASUR.TIME.READ_DIGITAL', 'Reads a digital time as one number, as 745 or ''seven hundred and forty-five''.', '{"question":"Read the digital clock 7:45.","wrong_answer":"seven hundred and forty-five","correct_answer":"seven forty-five, quarter to eight"}'::jsonb, 'Ignores the colon.', 'The answer seven hundred and forty-five as a wrong option, with a reason that names the idea.', 'The colon splits hours from minutes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.TIME.READ_DIGITAL.M_DIG_45_QUARTER_PAST', 'MATH.G3.MEASUR.TIME.READ_DIGITAL', 'Reads :45 as quarter past.', '{"question":"What is 3:45 on an analogue clock?","wrong_answer":"quarter past 3","correct_answer":"quarter to 4"}'::jsonb, 'Links 45 with a quarter but not with which quarter.', 'The answer quarter past 3 as a wrong option, with a reason that names the idea.', '45 minutes past is 15 minutes to the next hour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.TIME.READ_DIGITAL.M_DIG_MINUTES_UNDER_10', 'MATH.G3.MEASUR.TIME.READ_DIGITAL', 'Reads 4:05 as 4:50 or as ''four five past''.', '{"question":"What time is 4:05?","wrong_answer":"ten to five","correct_answer":"five past four"}'::jsonb, 'Reads the 0 as nothing or swaps the digits.', 'The answer ten to five as a wrong option, with a reason that names the idea.', 'Minutes always have two digits: 05 is 5 minutes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.TIME.READ_DIGITAL.M_DIG_HOUR_FOR_TO', 'MATH.G3.MEASUR.TIME.READ_DIGITAL', 'Gives the same hour for a ''to'' time, as 6:40 = 20 to 6.', '{"question":"What is 6:40 in words?","wrong_answer":"twenty to six","correct_answer":"twenty to seven"}'::jsonb, 'Keeps the hour shown instead of the next hour.', 'The answer twenty to six as a wrong option, with a reason that names the idea.', '''To'' counts towards the next hour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.TIME.WRITE_PAST_TO.M_WPT_FIVE_PAST_FOR_FIFTEEN', 'MATH.G3.MEASUR.TIME.WRITE_PAST_TO', 'Writes the number the hand points to instead of the minutes.', '{"question":"The long hand is on 5, the short hand just past 2. Write the time.","wrong_answer":"five past two","correct_answer":"twenty-five past two"}'::jsonb, 'Uses the clock number as the minutes.', 'The answer five past two as a wrong option, with a reason that names the idea.', 'Count in fives: 5, 10, 15, 20, 25.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.TIME.WRITE_PAST_TO.M_WPT_HANDS_SAME_LENGTH', 'MATH.G3.MEASUR.TIME.WRITE_PAST_TO', 'Draws both hands the same length, or the hour hand on the hour number for a half-past time.', '{"question":"Draw half past 3.","wrong_answer":"short hand exactly on 3","correct_answer":"short hand half way between 3 and 4"}'::jsonb, 'Thinks the hour hand stays on the number.', 'The answer short hand exactly on 3 as a wrong option, with a reason that names the idea.', 'Watch a real clock: the hour hand moves slowly between numbers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.TIME.WRITE_PAST_TO.M_WPT_PAST_TO_WORD_SWAP', 'MATH.G3.MEASUR.TIME.WRITE_PAST_TO', 'Writes ''past'' with the next hour, as ''twenty past five'' for 4:20.', '{"question":"Write 4:20 in words.","wrong_answer":"twenty past five","correct_answer":"twenty past four"}'::jsonb, 'Mixes the hour used with past and to.', 'The answer twenty past five as a wrong option, with a reason that names the idea.', 'Past uses the hour just gone; to uses the next hour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.TIME.WRITE_PAST_TO.M_WPT_THIRTY_TO', 'MATH.G3.MEASUR.TIME.WRITE_PAST_TO', 'Writes ''thirty to'' instead of half past.', '{"question":"Write the time when the long hand is on 6 and the short hand between 7 and 8.","wrong_answer":"thirty to eight","correct_answer":"half past seven"}'::jsonb, 'Does not know the half-past name.', 'The answer thirty to eight as a wrong option, with a reason that names the idea.', 'On 6 it is half way round: half past.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.TIME.ESTIMATE_HOURS.M_EH_WILD', 'MATH.G3.MEASUR.TIME.ESTIMATE_HOURS', 'Gives an estimate far from real, such as 20 hours for a school day.', '{"question":"About how many hours is a school day?","wrong_answer":"20 hours","correct_answer":"about 7 hours"}'::jsonb, 'Has no feel for an hour.', 'The answer 20 hours as a wrong option, with a reason that names the idea.', 'Count the hours from 8 o''clock to 3 o''clock on a clock.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.TIME.ESTIMATE_HOURS.M_EH_MINUTES_AS_HOURS', 'MATH.G3.MEASUR.TIME.ESTIMATE_HOURS', 'Gives a short activity in hours.', '{"question":"About how long does it take to eat lunch?","wrong_answer":"3 hours","correct_answer":"less than an hour"}'::jsonb, 'Mixes minutes and hours.', 'The answer 3 hours as a wrong option, with a reason that names the idea.', 'A lesson is less than an hour; lunch is shorter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.TIME.ESTIMATE_HOURS.M_EH_MORE_LESS_SWAP', 'MATH.G3.MEASUR.TIME.ESTIMATE_HOURS', 'Says an activity takes less than an hour when it takes much more.', '{"question":"Does a night''s sleep take more or less than an hour?","wrong_answer":"less","correct_answer":"more"}'::jsonb, 'Mixes more and less.', 'The answer less as a wrong option, with a reason that names the idea.', 'Think from going to bed to waking.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.TIME.ESTIMATE_HOURS.M_EH_ORDER', 'MATH.G3.MEASUR.TIME.ESTIMATE_HOURS', 'Orders activities by how much they are liked, not by time.', '{"question":"Put in order from shortest: a football match, brushing teeth, a school day.","wrong_answer":"school day, football match, brushing teeth","correct_answer":"brushing teeth, football match, school day"}'::jsonb, 'Does not compare durations.', 'The answer school day, football match, brushing teeth as a wrong option, with a reason that names the idea.', 'Ask for each: minutes or hours?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.TIME.ADD_TIME.M_ADDT_HOURS_TO_MINUTES', 'MATH.G3.MEASUR.TIME.ADD_TIME', 'Adds the hours to the minutes.', '{"question":"2 h 15 min + 1 h 30 min","wrong_answer":"2 h 46 min","correct_answer":"3 h 45 min"}'::jsonb, 'Puts all the numbers in one column.', 'The answer 2 h 46 min as a wrong option, with a reason that names the idea.', 'Two columns: h and min. Add each on its own.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.TIME.ADD_TIME.M_ADDT_DROPS_UNITS', 'MATH.G3.MEASUR.TIME.ADD_TIME', 'Writes the answer as one number, such as 345.', '{"question":"2 h 15 min + 1 h 30 min","wrong_answer":"345","correct_answer":"3 h 45 min"}'::jsonb, 'Treats the time as a 3-digit number.', 'The answer 345 as a wrong option, with a reason that names the idea.', 'Write h and min every time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.TIME.ADD_TIME.M_ADDT_ONLY_MINUTES', 'MATH.G3.MEASUR.TIME.ADD_TIME', 'Adds the minutes and forgets the hours.', '{"question":"1 h 20 min + 2 h 10 min","wrong_answer":"30 min","correct_answer":"3 h 30 min"}'::jsonb, 'Stops after one column.', 'The answer 30 min as a wrong option, with a reason that names the idea.', 'Tick each column after adding it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.TIME.ADD_TIME.M_ADDT_SUBTRACTS', 'MATH.G3.MEASUR.TIME.ADD_TIME', 'Subtracts when the story asks for total time.', '{"question":"A trip takes 2 h 10 min, then 1 h 20 min more. How long in all?","wrong_answer":"50 min","correct_answer":"3 h 30 min"}'::jsonb, 'Takes away because of the word more, wrongly.', 'The answer 50 min as a wrong option, with a reason that names the idea.', 'In all: add.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.TIME.SUBTRACT_TIME.M_SUBT_MIXES_COLUMNS', 'MATH.G3.MEASUR.TIME.SUBTRACT_TIME', 'Takes minutes from hours.', '{"question":"3 h 50 min - 1 h 20 min","wrong_answer":"2 h 49 min","correct_answer":"2 h 30 min"}'::jsonb, 'Lines up wrongly.', 'The answer 2 h 49 min as a wrong option, with a reason that names the idea.', 'Hours from hours, minutes from minutes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.TIME.SUBTRACT_TIME.M_SUBT_ADDS', 'MATH.G3.MEASUR.TIME.SUBTRACT_TIME', 'Adds when asked how much longer.', '{"question":"A film lasts 2 h 40 min and a match 1 h 30 min. How much longer is the film?","wrong_answer":"4 h 10 min","correct_answer":"1 h 10 min"}'::jsonb, 'Longer sounds like more.', 'The answer 4 h 10 min as a wrong option, with a reason that names the idea.', 'The extra time is the difference.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.TIME.SUBTRACT_TIME.M_SUBT_COUNTS_HOUR_NUMBERS', 'MATH.G3.MEASUR.TIME.SUBTRACT_TIME', 'Finds how long from one o''clock time to another by counting the hour numbers, so gets one hour too many.', '{"question":"How long is it from 2 o''clock to 5 o''clock?","wrong_answer":"4 hours","correct_answer":"3 hours"}'::jsonb, 'Counts 2, 3, 4, 5 as four hours.', 'The answer 4 hours as a wrong option, with a reason that names the idea.', 'Count the jumps between the numbers, not the numbers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.TIME.SUBTRACT_TIME.M_SUBT_GIVES_TIME_USED', 'MATH.G3.MEASUR.TIME.SUBTRACT_TIME', 'Gives the time used instead of the time left.', '{"question":"A 3 h 40 min trip: 1 h 10 min done. How long is left?","wrong_answer":"1 h 10 min","correct_answer":"2 h 30 min"}'::jsonb, 'Repeats a number from the story.', 'The answer 1 h 10 min as a wrong option, with a reason that names the idea.', 'Draw a time bar and shade what is done.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
