INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.MONEY.SUBTRACT_MONEY.M_SUBM_ADDS', 'MATH.G3.MEASUR.MONEY.SUBTRACT_MONEY', 'Adds when asked how much is left.', '{"question":"Juma has sh. 600 and spends sh. 250. How much is left?","wrong_answer":"sh. 850","correct_answer":"sh. 350"}'::jsonb, 'Sees two numbers and adds.', 'The answer sh. 850 as a wrong option, with a reason that names the idea.', 'Spending makes less.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.MONEY.SUBTRACT_MONEY.M_SUBM_GIVES_SPENT', 'MATH.G3.MEASUR.MONEY.SUBTRACT_MONEY', 'Gives the amount spent as the money left.', '{"question":"Achieng had sh. 400 and spent sh. 150. How much is left?","wrong_answer":"sh. 150","correct_answer":"sh. 250"}'::jsonb, 'Repeats a number.', 'The answer sh. 150 as a wrong option, with a reason that names the idea.', 'Draw the money and cross off what is spent.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.MONEY.SUBTRACT_MONEY.M_SUBM_HOW_MUCH_MORE_ADDS', 'MATH.G3.MEASUR.MONEY.SUBTRACT_MONEY', 'Adds when asked how much more one item costs.', '{"question":"A bag costs sh. 450 and a book sh. 200. How much more is the bag?","wrong_answer":"sh. 650","correct_answer":"sh. 250"}'::jsonb, '''More'' sounds like add.', 'The answer sh. 650 as a wrong option, with a reason that names the idea.', 'How much more is the gap between them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.MONEY.SAME_AMOUNT_WAYS.M_SAME_COUNTS_PIECES', 'MATH.G3.MEASUR.MONEY.SAME_AMOUNT_WAYS', 'Thinks a collection with more pieces is worth more.', '{"question":"Are two sh. 100 notes worth the same as one sh. 200 note?","wrong_answer":"no, two notes are more","correct_answer":"yes"}'::jsonb, 'Counts notes.', 'The answer no, two notes are more as a wrong option, with a reason that names the idea.', 'Count the value of each collection.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.MONEY.SAME_AMOUNT_WAYS.M_SAME_WRONG_NUMBER', 'MATH.G3.MEASUR.MONEY.SAME_AMOUNT_WAYS', 'Uses the wrong number of the smaller note.', '{"question":"How many sh. 50 notes make sh. 200?","wrong_answer":"2","correct_answer":"4"}'::jsonb, 'Thinks of halving once.', 'The answer 2 as a wrong option, with a reason that names the idea.', 'Count in fifties: 50, 100, 150, 200.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.MONEY.SAME_AMOUNT_WAYS.M_SAME_ONE_WAY_ONLY', 'MATH.G3.MEASUR.MONEY.SAME_AMOUNT_WAYS', 'Thinks an amount can only be shown one way.', '{"question":"Show sh. 500 another way than one sh. 500 note.","wrong_answer":"cannot","correct_answer":"five sh. 100 notes"}'::jsonb, 'Has not seen that values can be swapped.', 'The answer cannot as a wrong option, with a reason that names the idea.', 'Exchange at the model shop: one note for smaller ones.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.MONEY.SAME_AMOUNT_WAYS.M_SAME_ADDS_FACE_VALUES_WRONG', 'MATH.G3.MEASUR.MONEY.SAME_AMOUNT_WAYS', 'Adds the numbers on the notes wrongly when checking, as 200 + 200 + 100 = 400.', '{"question":"Do two sh. 200 notes and one sh. 100 note make sh. 500?","wrong_answer":"no, sh. 400","correct_answer":"yes"}'::jsonb, 'Addition slip.', 'The answer no, sh. 400 as a wrong option, with a reason that names the idea.', 'Count on: 200, 400, 500.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.MONEY.CHANGE_DENOMINATIONS.M_CHG_WRONG_COUNT', 'MATH.G3.MEASUR.MONEY.CHANGE_DENOMINATIONS', 'Gives the wrong number of smaller notes in exchange.', '{"question":"Change a sh. 1,000 note into sh. 200 notes. How many?","wrong_answer":"10","correct_answer":"5"}'::jsonb, 'Divides by the wrong number or counts in hundreds.', 'The answer 10 as a wrong option, with a reason that names the idea.', 'Count in two hundreds to 1,000.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.MONEY.CHANGE_DENOMINATIONS.M_CHG_THINKS_LOSES_VALUE', 'MATH.G3.MEASUR.MONEY.CHANGE_DENOMINATIONS', 'Thinks changing a note for coins loses money because coins are small.', '{"question":"Is a sh. 100 note changed for five sh. 20 coins a fair exchange?","wrong_answer":"no","correct_answer":"yes"}'::jsonb, 'Judges value by size.', 'The answer no as a wrong option, with a reason that names the idea.', 'Count the coins'' value.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.MONEY.CHANGE_DENOMINATIONS.M_CHG_MISSING_PART', 'MATH.G3.MEASUR.MONEY.CHANGE_DENOMINATIONS', 'Cannot find the missing part of the change.', '{"question":"A sh. 500 note is changed into sh. 200 and some sh. 100 notes. How many sh. 100 notes?","wrong_answer":"2","correct_answer":"3"}'::jsonb, 'Takes the 200 as two 100s twice.', 'The answer 2 as a wrong option, with a reason that names the idea.', '500 - 200 = 300: count the hundreds in 300.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.MONEY.CHANGE_DENOMINATIONS.M_CHG_GIVES_VALUE_NOT_COUNT', 'MATH.G3.MEASUR.MONEY.CHANGE_DENOMINATIONS', 'Gives the value of each smaller note instead of how many.', '{"question":"How many sh. 50 notes for a sh. 100 note?","wrong_answer":"50","correct_answer":"2"}'::jsonb, 'Answers with the note''s value.', 'The answer 50 as a wrong option, with a reason that names the idea.', 'Ask ''how many notes?''', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.MONEY.BUY_WITH_BALANCE.M_MONEY_GIVES_COST_AS_CHANGE', 'MATH.G3.MEASUR.MONEY.BUY_WITH_BALANCE', 'Gives the total cost as the balance.', '{"question":"Bread sh. 60 and milk sh. 70, paid with sh. 200. Change?","wrong_answer":"sh. 130","correct_answer":"sh. 70"}'::jsonb, 'Stops after adding.', 'The answer sh. 130 as a wrong option, with a reason that names the idea.', 'Balance is money paid minus cost.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.MONEY.BUY_WITH_BALANCE.M_MONEY_PAYS_ONE_ITEM', 'MATH.G3.MEASUR.MONEY.BUY_WITH_BALANCE', 'Takes only one item''s price from the money paid.', '{"question":"Bread sh. 60 and milk sh. 70, paid with sh. 200. Change?","wrong_answer":"sh. 140","correct_answer":"sh. 70"}'::jsonb, 'Forgets the other item.', 'The answer sh. 140 as a wrong option, with a reason that names the idea.', 'Add all the items first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.MONEY.BUY_WITH_BALANCE.M_MONEY_ADDS_PAID_AND_COST', 'MATH.G3.MEASUR.MONEY.BUY_WITH_BALANCE', 'Adds the money paid and the cost.', '{"question":"A ball costs sh. 350. Paid with sh. 500. Change?","wrong_answer":"sh. 850","correct_answer":"sh. 150"}'::jsonb, 'Adds the two numbers.', 'The answer sh. 850 as a wrong option, with a reason that names the idea.', 'Change is what comes back: less than what was paid.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.MEASUR.MONEY.BUY_WITH_BALANCE.M_MONEY_CHANGE_NO_CHECK', 'MATH.G3.MEASUR.MONEY.BUY_WITH_BALANCE', 'Gives a change that, with the cost, is more than the money paid.', '{"question":"Items cost sh. 380. Paid sh. 500. Change?","wrong_answer":"sh. 220","correct_answer":"sh. 120"}'::jsonb, 'Subtraction slip not checked.', 'The answer sh. 220 as a wrong option, with a reason that names the idea.', 'Check: cost + change = money paid.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.GEOMET.POSITION_AND_DIRECTION.MOVE_STRAIGHT.M_MOVE_COUNTS_START', 'MATH.G3.GEOMET.POSITION_AND_DIRECTION.MOVE_STRAIGHT', 'Counts the starting square as the first step.', '{"question":"A counter is on square 3 of a straight path. It moves 4 steps forward. Where is it?","wrong_answer":"6","correct_answer":"7"}'::jsonb, 'Says ''one'' on the square it starts on.', 'The answer 6 as a wrong option, with a reason that names the idea.', 'Count only when the counter lands on a new square.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.GEOMET.POSITION_AND_DIRECTION.MOVE_STRAIGHT.M_MOVE_DIRECTION', 'MATH.G3.GEOMET.POSITION_AND_DIRECTION.MOVE_STRAIGHT', 'Moves backwards when told forwards, or the reverse.', '{"question":"Start at the tree and walk 5 steps back towards the gate. Are you nearer the tree or the gate?","wrong_answer":"the tree","correct_answer":"the gate"}'::jsonb, 'Mixes forward and back.', 'The answer the tree as a wrong option, with a reason that names the idea.', 'Point the way before moving.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.GEOMET.POSITION_AND_DIRECTION.MOVE_STRAIGHT.M_MOVE_NOT_STRAIGHT', 'MATH.G3.GEOMET.POSITION_AND_DIRECTION.MOVE_STRAIGHT', 'Thinks a bending path is a straight line.', '{"question":"Is a path round a flower bed a straight line?","wrong_answer":"yes","correct_answer":"no"}'::jsonb, 'Calls any path a line.', 'The answer yes as a wrong option, with a reason that names the idea.', 'A straight line does not bend: check with a stretched string.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.GEOMET.POSITION_AND_DIRECTION.MOVE_STRAIGHT.M_MOVE_STEPS_FROM_WRONG_POINT', 'MATH.G3.GEOMET.POSITION_AND_DIRECTION.MOVE_STRAIGHT', 'Counts steps from the wrong starting point.', '{"question":"From the door, Amina walks 6 steps to the desk. From the desk she walks 3 more. How many steps from the door?","wrong_answer":"3","correct_answer":"9"}'::jsonb, 'Counts only the last move.', 'The answer 3 as a wrong option, with a reason that names the idea.', 'Mark the starting point and add every move from it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.GEOMET.POSITION_AND_DIRECTION.LEFT_RIGHT.M_LR_MIRROR', 'MATH.G3.GEOMET.POSITION_AND_DIRECTION.LEFT_RIGHT', 'Gives his own right for the right of a person facing him.', '{"question":"Kamau faces you and raises his right hand. Is it on your right or your left?","wrong_answer":"my right","correct_answer":"my left"}'::jsonb, 'Uses his own body, not Kamau''s.', 'The answer my right as a wrong option, with a reason that names the idea.', 'Stand beside the person, facing the same way.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.GEOMET.POSITION_AND_DIRECTION.LEFT_RIGHT.M_LR_SWAP', 'MATH.G3.GEOMET.POSITION_AND_DIRECTION.LEFT_RIGHT', 'Mixes up right and left on their own body.', '{"question":"Hold up your left hand.","wrong_answer":"right hand","correct_answer":"left hand"}'::jsonb, 'Has not fixed the names.', 'The answer right hand as a wrong option, with a reason that names the idea.', 'The left hand makes an L with thumb and finger.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.GEOMET.POSITION_AND_DIRECTION.LEFT_RIGHT.M_LR_PICTURE_VIEWER', 'MATH.G3.GEOMET.POSITION_AND_DIRECTION.LEFT_RIGHT', 'Uses the viewer''s left and right for a person in a picture facing out.', '{"question":"A boy in a picture faces you. A ball is by his right hand. Which side of the page is it on?","wrong_answer":"the right side","correct_answer":"the left side"}'::jsonb, 'Reads the page sides as the boy''s sides.', 'The answer the right side as a wrong option, with a reason that names the idea.', 'Turn the picture: what would the boy''s right be?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.GEOMET.POSITION_AND_DIRECTION.LEFT_RIGHT.M_LR_FRONT_BEHIND_CONFUSED', 'MATH.G3.GEOMET.POSITION_AND_DIRECTION.LEFT_RIGHT', 'Answers front or behind when asked right or left.', '{"question":"What is on your right when you face the board?","wrong_answer":"the board","correct_answer":"the window (side wall)"}'::jsonb, 'Mixes facing with sides.', 'The answer the board as a wrong option, with a reason that names the idea.', 'Right and left are the sides, not the front.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.GEOMET.POSITION_AND_DIRECTION.TURN_LEFT_RIGHT.M_TURN_LEFT_RIGHT_SWAPPED', 'MATH.G3.GEOMET.POSITION_AND_DIRECTION.TURN_LEFT_RIGHT', 'Turns left when told to turn right.', '{"question":"You face the gate and turn right. Do you face the side with the office or the side with the field (office on your right)?","wrong_answer":"the field","correct_answer":"the office"}'::jsonb, 'Mixes the names when turning.', 'The answer the field as a wrong option, with a reason that names the idea.', 'Raise the right hand, then turn to face where it points.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.GEOMET.POSITION_AND_DIRECTION.TURN_LEFT_RIGHT.M_TURN_HALF_TURN', 'MATH.G3.GEOMET.POSITION_AND_DIRECTION.TURN_LEFT_RIGHT', 'Makes a half turn, ending up facing back.', '{"question":"You face the board and turn right. Do you face the back wall?","wrong_answer":"yes","correct_answer":"no, the right side wall"}'::jsonb, 'Turns too far.', 'The answer yes as a wrong option, with a reason that names the idea.', 'A turn to the right is a quarter turn: only to the side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.GEOMET.POSITION_AND_DIRECTION.TURN_LEFT_RIGHT.M_TURN_FROM_START_FACING', 'MATH.G3.GEOMET.POSITION_AND_DIRECTION.TURN_LEFT_RIGHT', 'In a route, makes each turn from the first facing, not the new one.', '{"question":"Walk forward, turn right, walk, turn right again. Which way do you face now?","wrong_answer":"the same as after the first turn","correct_answer":"back the way you started"}'::jsonb, 'Forgets that turning changes the facing.', 'The answer the same as after the first turn as a wrong option, with a reason that names the idea.', 'Act it out; after each turn your right is new.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.GEOMET.POSITION_AND_DIRECTION.TURN_LEFT_RIGHT.M_TURN_MOVES_SIDEWAYS', 'MATH.G3.GEOMET.POSITION_AND_DIRECTION.TURN_LEFT_RIGHT', 'Steps sideways instead of turning the body.', '{"question":"Turn left: do you step to the left side, or turn to face it?","wrong_answer":"step sideways","correct_answer":"turn to face the left"}'::jsonb, 'Reads turn as move.', 'The answer step sideways as a wrong option, with a reason that names the idea.', 'Keep your feet on the spot and turn your body.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.GEOMET.SHAPES.NAME_SHAPES.M_SHAPE_TURNED_SQUARE', 'MATH.G3.GEOMET.SHAPES.NAME_SHAPES', 'Calls a square turned on its corner a diamond and says it is not a square.', '{"question":"A square is turned so a corner points up. Is it still a square?","wrong_answer":"no, a diamond","correct_answer":"yes"}'::jsonb, 'Thinks turning changes the shape.', 'The answer no, a diamond as a wrong option, with a reason that names the idea.', 'Turn a square cut-out and count its equal sides.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.GEOMET.SHAPES.NAME_SHAPES.M_SHAPE_OVAL_CIRCLE', 'MATH.G3.GEOMET.SHAPES.NAME_SHAPES', 'Calls an oval a circle.', '{"question":"An egg shape: circle or oval?","wrong_answer":"circle","correct_answer":"oval"}'::jsonb, 'Thinks every round shape is a circle.', 'The answer circle as a wrong option, with a reason that names the idea.', 'A circle is the same across every way; an oval is longer one way.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.GEOMET.SHAPES.NAME_SHAPES.M_SHAPE_SQUARE_NOT_RECTANGLE', 'MATH.G3.GEOMET.SHAPES.NAME_SHAPES', 'Calls a long rectangle a square, or a square a triangle, by counting corners wrongly.', '{"question":"A shape has 4 sides: 2 long and 2 short. What is it?","wrong_answer":"square","correct_answer":"rectangle"}'::jsonb, 'Thinks every 4-sided shape is a square.', 'The answer square as a wrong option, with a reason that names the idea.', 'A square has 4 equal sides; a rectangle has 2 long and 2 short.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.GEOMET.SHAPES.NAME_SHAPES.M_SHAPE_TRIANGLE_UPRIGHT_ONLY', 'MATH.G3.GEOMET.SHAPES.NAME_SHAPES', 'Says a triangle standing on its point, or a long thin one, is not a triangle.', '{"question":"A shape with 3 straight sides points down. Is it a triangle?","wrong_answer":"no","correct_answer":"yes"}'::jsonb, 'Has only seen triangles standing on a base.', 'The answer no as a wrong option, with a reason that names the idea.', 'Count the sides: any 3-sided shape is a triangle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.GEOMET.SHAPES.SHAPES_IN_COMBINED.M_COMB_ONE_SHAPE', 'MATH.G3.GEOMET.SHAPES.SHAPES_IN_COMBINED', 'Sees the combined shape as one new shape and cannot name its parts.', '{"question":"A hut drawing: which two shapes make it?","wrong_answer":"a hut","correct_answer":"a triangle and a rectangle"}'::jsonb, 'Sees the object, not the shapes.', 'The answer a hut as a wrong option, with a reason that names the idea.', 'Cover the top: what shape is left? Then cover the bottom.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.GEOMET.SHAPES.SHAPES_IN_COMBINED.M_COMB_COUNTS_SIDES_TOTAL', 'MATH.G3.GEOMET.SHAPES.SHAPES_IN_COMBINED', 'Counts all the outside sides and names a shape with that many sides.', '{"question":"A triangle on a square makes a house. Which two shapes?","wrong_answer":"a pentagon","correct_answer":"a triangle and a square"}'::jsonb, 'Counts the outline.', 'The answer a pentagon as a wrong option, with a reason that names the idea.', 'Look for the line inside that splits the two shapes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.GEOMET.SHAPES.SHAPES_IN_COMBINED.M_COMB_SAME_SHAPE_TWICE', 'MATH.G3.GEOMET.SHAPES.SHAPES_IN_COMBINED', 'Names one shape twice, as two triangles for a cone.', '{"question":"An ice cream cone: which two shapes?","wrong_answer":"two triangles","correct_answer":"a triangle and a circle"}'::jsonb, 'Names the shape seen first for both parts.', 'The answer two triangles as a wrong option, with a reason that names the idea.', 'Point to each part on its own and name it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.GEOMET.SHAPES.SHAPES_IN_COMBINED.M_COMB_WRONG_PART_NAME', 'MATH.G3.GEOMET.SHAPES.SHAPES_IN_COMBINED', 'Names the parts by their use (roof, door) instead of their shape.', '{"question":"What shape is the roof of the hut drawing?","wrong_answer":"roof","correct_answer":"triangle"}'::jsonb, 'Answers with the object''s name.', 'The answer roof as a wrong option, with a reason that names the idea.', 'Ask ''what shape?'', not ''what is it?''', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.GEOMET.SHAPES.DRAW_COMBINED.M_DRAW_GAP', 'MATH.G3.GEOMET.SHAPES.DRAW_COMBINED', 'Draws the two shapes apart instead of joined.', '{"question":"Draw a triangle on top of a square to make a house. Are the shapes touching?","wrong_answer":"drawn apart","correct_answer":"sharing one side"}'::jsonb, 'Draws the two shapes separately.', 'The answer drawn apart as a wrong option, with a reason that names the idea.', 'Draw the square first, then use its top side as the triangle''s base.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.GEOMET.SHAPES.DRAW_COMBINED.M_DRAW_WRONG_SIDES', 'MATH.G3.GEOMET.SHAPES.DRAW_COMBINED', 'Draws one of the parts with the wrong number of sides.', '{"question":"Draw a rectangle with a triangle on it. How many sides does your triangle have?","wrong_answer":"4","correct_answer":"3"}'::jsonb, 'Draws freehand without counting.', 'The answer 4 as a wrong option, with a reason that names the idea.', 'Count the sides as you draw.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.GEOMET.SHAPES.DRAW_COMBINED.M_DRAW_CURVED_FOR_STRAIGHT', 'MATH.G3.GEOMET.SHAPES.DRAW_COMBINED', 'Draws curved sides for a shape with straight sides.', '{"question":"Draw a hut: square walls and triangle roof. Are your lines straight?","wrong_answer":"curved","correct_answer":"straight"}'::jsonb, 'Draws quickly without a ruler.', 'The answer curved as a wrong option, with a reason that names the idea.', 'Use a ruler for straight sides.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.GEOMET.SHAPES.DRAW_COMBINED.M_DRAW_THREE_SHAPES', 'MATH.G3.GEOMET.SHAPES.DRAW_COMBINED', 'Adds a third shape, so it is no longer made of two.', '{"question":"Draw a combined shape of two shapes: a rectangle and a triangle.","wrong_answer":"rectangle, triangle and circle","correct_answer":"rectangle and triangle"}'::jsonb, 'Decorates the drawing.', 'The answer rectangle, triangle and circle as a wrong option, with a reason that names the idea.', 'Count the shapes in your drawing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.GEOMET.SHAPES.MODEL_COMBINED.M_MODEL_WRONG_PIECE', 'MATH.G3.GEOMET.SHAPES.MODEL_COMBINED', 'Picks a cut-out of the wrong shape for one part.', '{"question":"Model a hut with a rectangle and a triangle. Which pieces?","wrong_answer":"a rectangle and a circle","correct_answer":"a rectangle and a triangle"}'::jsonb, 'Picks by colour or size.', 'The answer a rectangle and a circle as a wrong option, with a reason that names the idea.', 'Name each piece before using it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.GEOMET.SHAPES.MODEL_COMBINED.M_MODEL_NOT_JOINED', 'MATH.G3.GEOMET.SHAPES.MODEL_COMBINED', 'Lays the pieces apart instead of joining them along a side.', '{"question":"Is a triangle placed far from a rectangle a combined shape?","wrong_answer":"yes","correct_answer":"no"}'::jsonb, 'Does not see that the parts must share an edge.', 'The answer yes as a wrong option, with a reason that names the idea.', 'Slide the pieces until a side touches.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.GEOMET.SHAPES.MODEL_COMBINED.M_MODEL_OVERLAP_HIDES', 'MATH.G3.GEOMET.SHAPES.MODEL_COMBINED', 'Overlaps the pieces so one shape is hidden.', '{"question":"If the triangle covers half the rectangle, can you still see both shapes?","wrong_answer":"yes","correct_answer":"no, part is hidden"}'::jsonb, 'Puts one piece on top of the other.', 'The answer yes as a wrong option, with a reason that names the idea.', 'Put the pieces side by side, edges touching.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G3.GEOMET.SHAPES.MODEL_COMBINED.M_MODEL_NAMES_OBJECT', 'MATH.G3.GEOMET.SHAPES.MODEL_COMBINED', 'Names the model as the object only and not its two shapes.', '{"question":"What shapes is your model made of?","wrong_answer":"a house","correct_answer":"a square and a triangle"}'::jsonb, 'Answers with the object.', 'The answer a house as a wrong option, with a reason that names the idea.', 'Ask: which shapes did you use?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
